import { boolean, index, integer, jsonb, pgEnum, pgTable, text, timestamp } from "drizzle-orm/pg-core";
import { nanoid } from "nanoid";
// ============================================================================
// Enums
// ============================================================================
// Pioneer tiers removed per CANON.md (April decision)
// No tier names: Seedling, Grower, Cultivator, Guardian are dead
// No point actions, weekly caps, or leaderboard mechanics
// No gamification of any kind
export const pioneerCodeStatusEnum = pgEnum("pioneer_code_status", [
    "active",
    "exhausted",
    "deactivated",
    "expired",
    "revoked",
]);
// ============================================================================
// pioneers
// ============================================================================
export const pioneers = pgTable("pioneers", {
    id: text("id")
        .primaryKey()
        .$defaultFn(() => nanoid()),
    userId: text("user_id").notNull().unique(),
    username: text("username").notNull(),
    githubId: text("github_id").notNull().unique(),
    contactEmail: text("contact_email"),
    // Tier and points removed per CANON.md (April decision)
    joinedAt: timestamp("joined_at").notNull().defaultNow(),
    referralCode: text("referral_code").notNull().unique(),
    githubStarred: boolean("github_starred").notNull().default(false),
    // Leaderboard visibility removed per CANON.md
    referredBy: text("referred_by"),
    lastSyncedAt: timestamp("last_synced_at"),
    // Survey fields (Spec 2 Phase 5)
    surveyCompletedAt: timestamp("survey_completed_at"),
    experienceLevel: text("experience_level"),
    codebaseSize: text("codebase_size"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
    updatedAt: timestamp("updated_at").notNull().defaultNow(),
}, (t) => []);
// ============================================================================
// pioneer_actions - REMOVED per CANON.md (April decision)
// No point actions, weekly caps, or leaderboard mechanics
// ============================================================================
// ============================================================================
// pioneer_tier_history - REMOVED per CANON.md (April decision)
// No tier names or progression
// ============================================================================
// ============================================================================
// pioneer_codes
// ============================================================================
export const pioneerCodes = pgTable("pioneer_codes", {
    id: text("id")
        .primaryKey()
        .$defaultFn(() => nanoid()),
    code: text("code").notNull().unique(),
    createdBy: text("created_by"),
    maxRedemptions: integer("max_redemptions").notNull().default(1),
    currentRedemptions: integer("current_redemptions").notNull().default(0),
    status: pioneerCodeStatusEnum("status").notNull().default("active"),
    cohort: integer("cohort").notNull().default(1),
    label: text("label"),
    expiresAt: timestamp("expires_at"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
    updatedAt: timestamp("updated_at").notNull().defaultNow(),
}, (t) => [index("pioneer_codes_status_idx").on(t.status), index("pioneer_codes_cohort_idx").on(t.cohort)]);
// ============================================================================
// pioneer_redemptions
// ============================================================================
export const pioneerRedemptions = pgTable("pioneer_redemptions", {
    id: text("id")
        .primaryKey()
        .$defaultFn(() => nanoid()),
    codeId: text("code_id").notNull(),
    userId: text("user_id").notNull().unique(),
    pioneerId: text("pioneer_id"),
    primaryIde: text("primary_ide").notNull(),
    aiTools: jsonb("ai_tools").notNull().default([]),
    redeemedAt: timestamp("redeemed_at").defaultNow(),
    hubspotSyncedAt: timestamp("hubspot_synced_at"),
    posthogSyncedAt: timestamp("posthog_synced_at"),
    welcomeEmailSentAt: timestamp("welcome_email_sent_at"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
}, (t) => [
    index("pioneer_redemptions_code_id_idx").on(t.codeId),
    index("pioneer_redemptions_pioneer_id_idx").on(t.pioneerId),
]);
