import { boolean, integer, jsonb, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";
/**
 * Telemetry Event Outbox Table
 *
 * Transactional Outbox Pattern for telemetry events.
 * Ensures events are durably recorded before being sent to PostHog.
 *
 * Pattern: Write event + outbox in same transaction → Background worker processes outbox
 * Enables exactly-once delivery, audit trail, and automatic retry.
 *
 * @see .vreko/audit/leak_map_proven.md for full pipeline documentation
 * @see packages/platform/src/schema/pioneer-event-outbox.ts for reference implementation
 */
export const telemetryOutbox = pgTable("telemetry_outbox", {
    id: uuid("id").primaryKey().defaultRandom(),
    // Event identification
    eventType: text("event_type").notNull(), // 'save_attempt', 'snapshot_created', etc.
    userId: text("user_id"), // User who triggered the event
    // Event data
    payload: jsonb("payload").notNull(), // Full event properties (filtered)
    posthogPayload: jsonb("posthog_payload").notNull(), // Formatted for PostHog.capture()
    // Processing status
    processed: boolean("processed").default(false),
    processedAt: timestamp("processed_at", { withTimezone: true }),
    processingErrors: jsonb("processing_errors").default([]), // Array of error objects
    retryCount: integer("retry_count").default(0),
    maxRetries: integer("max_retries").default(3),
    // Idempotency
    idempotencyKey: text("idempotency_key").notNull(), // Prevents duplicate events
    // Timestamps
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow(),
});
