// ESM imports fixed for Node.js v22+
/**
 * Codebase Bindings - Abuse Defense Phase 1
 *
 * Tracks codebase-to-account bindings for abuse prevention.
 * Links repositories to accounts via device bindings.
 *
 * PRIVACY: Only hashed codebase fingerprints are stored.
 * Git remote URLs are normalized before hashing.
 */
import { relations } from "drizzle-orm";
import { index, integer, pgTable, timestamp, uniqueIndex, varchar } from "drizzle-orm/pg-core";
import { user } from "../postgres.js";
/**
 * Codebase Bindings table - Maps codebase fingerprints to accounts
 */
export const codebaseBindings = pgTable("codebase_bindings", {
    id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
    /** Canonical codebase identity from daemon */
    codebaseHash: varchar("codebase_hash", { length: 64 }).notNull(),
    /** Initial commit hash  -  nullable (shallow clones, new repos) */
    repoSignature: varchar("repo_signature", { length: 64 }),
    /** Account this codebase is bound to */
    accountId: varchar("account_id", { length: 255 })
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    /** Device this binding was created from */
    machineIdHash: varchar("machine_id_hash", { length: 64 }).notNull(),
    /** User's tier at time of binding */
    tier: varchar("tier", { length: 20 }).notNull().default("free"),
    /** Which signals contributed to the fingerprint */
    signalSources: varchar("signal_sources", { length: 255 }),
    firstSeen: timestamp("first_seen", { withTimezone: true }).defaultNow().notNull(),
    lastSeen: timestamp("last_seen", { withTimezone: true }).defaultNow().notNull(),
}, (table) => [
    uniqueIndex("uq_codebase_account").on(table.codebaseHash, table.accountId),
    /** Index for account lookups */
    index("codebase_bindings_account_id_idx").on(table.accountId),
    /** Index for codebase hash lookups */
    index("codebase_bindings_hash_idx").on(table.codebaseHash),
]);
// Relations
export const codebaseBindingsRelations = relations(codebaseBindings, ({ one }) => ({
    account: one(user, {
        fields: [codebaseBindings.accountId],
        references: [user.id],
    }),
}));
