// ESM imports fixed for Node.js v22+
/**
 * Intelligence Layer Schema (Phase 1: Intelligence New Platform)
 *
 * Drizzle ORM schema for learnings, patterns, violations, and session context.
 * These tables sync from local StateStore to Neon PostgreSQL via CRDT.
 */
import { relations, sql } from "drizzle-orm";
import { boolean, index, integer, jsonb, pgTable, real, text, timestamp, unique, uuid } from "drizzle-orm/pg-core";
import { user } from "../postgres.js";
/**
 * Learnings Table - Individual learning records synced from StateStore
 */
export const learnings = pgTable("learnings", {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    workspaceId: text("workspace_id").notNull(),
    // Learning content
    type: text("type", {
        enum: ["pattern", "pitfall", "efficiency", "discovery", "workflow"],
    }).notNull(),
    trigger: text("trigger").notNull(),
    action: text("action").notNull(),
    keywords: jsonb("keywords").default([]).notNull(),
    source: text("source", { enum: ["survey", "manual", "violation", "curated"] }),
    tier: text("tier", { enum: ["hot", "warm", "cold"] }).notNull(),
    domain: text("domain"),
    // Usage tracking
    accessCount: integer("access_count").default(0).notNull(),
    appliedCount: integer("applied_count").default(0).notNull(),
    relevanceScore: real("relevance_score").default(1.0).notNull(),
    // Archival support (Phase 2.6b)
    archived: boolean("archived").default(false),
    archivedAt: timestamp("archived_at", { withTimezone: true }),
    // CRDT sync metadata
    syncVersion: integer("sync_version").default(0).notNull(),
    lastSyncedAt: timestamp("last_synced_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    lastAccessedAt: timestamp("last_accessed_at", { withTimezone: true }),
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
}, (table) => ({
    // Performance indexes for dashboard queries (P0-2)
    workspaceTierIdx: index("idx_learnings_workspace_tier")
        .on(table.workspaceId, table.tier)
        .where(sql `${table.archived} = false`),
    userActiveIdx: index("idx_learnings_user_active").on(table.userId, table.archived, table.tier),
}));
export const learningsRelations = relations(learnings, ({ one }) => ({
    user: one(user, {
        fields: [learnings.userId],
        references: [user.id],
    }),
}));
/**
 * Intelligence Patterns Table - Promoted patterns from violations
 * Note: Renamed to avoid conflict with existing patterns table (vector embeddings)
 */
export const intelligencePatterns = pgTable("intelligence_patterns", {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    workspaceId: text("workspace_id").notNull(),
    // Pattern content
    name: text("name").notNull(),
    description: text("description").notNull(),
    trigger: text("trigger").notNull(),
    action: text("action").notNull(),
    source: text("source", { enum: ["violation", "manual", "curated"] }).notNull(),
    confidence: real("confidence").default(0.5).notNull(),
    usageCount: integer("usage_count").default(0).notNull(),
    // Archival support
    archived: boolean("archived").default(false),
    // CRDT sync metadata
    syncVersion: integer("sync_version").default(0).notNull(),
    lastSyncedAt: timestamp("last_synced_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
}, (table) => ({
    // Performance indexes for pattern queries (P0-2)
    highConfIdx: index("idx_intelligence_patterns_high_conf")
        .on(table.confidence)
        .where(sql `${table.confidence} > 0.8`),
    activeIdx: index("idx_intelligence_patterns_active")
        .on(table.workspaceId, table.createdAt)
        .where(sql `${table.archived} = false`),
}));
export const intelligencePatternsRelations = relations(intelligencePatterns, ({ one }) => ({
    user: one(user, {
        fields: [intelligencePatterns.userId],
        references: [user.id],
    }),
}));
/**
 * Violations Table - Violation tracking for pattern promotion
 */
export const violations = pgTable("violations", {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    workspaceId: text("workspace_id").notNull(),
    // Violation content
    type: text("type").notNull(),
    file: text("file").notNull(),
    description: text("description").notNull(),
    reason: text("reason"),
    prevention: text("prevention").notNull(),
    // Tracking
    count: integer("count").default(1).notNull(),
    firstSeen: timestamp("first_seen", { withTimezone: true }).defaultNow().notNull(),
    lastSeen: timestamp("last_seen", { withTimezone: true }).defaultNow().notNull(),
    promotedToPattern: boolean("promoted_to_pattern").default(false),
    // CRDT sync metadata
    syncVersion: integer("sync_version").default(0).notNull(),
    lastSyncedAt: timestamp("last_synced_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
}, (table) => ({
    uniqueWorkspaceTypeFile: unique().on(table.workspaceId, table.type, table.file),
}));
export const violationsRelations = relations(violations, ({ one }) => ({
    user: one(user, {
        fields: [violations.userId],
        references: [user.id],
    }),
}));
/**
 * Session Context Table - Session-specific context with applied learnings
 */
export const sessionContext = pgTable("session_context", {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    workspaceId: text("workspace_id").notNull(),
    // Session metadata
    taskDescription: text("task_description"),
    startedAt: timestamp("started_at", { withTimezone: true }).notNull(),
    lastCheckpoint: timestamp("last_checkpoint", { withTimezone: true }).defaultNow().notNull(),
    snapshotId: text("snapshot_id"),
    context: jsonb("context").default({}).notNull(),
    // Applied learnings tracking (Phase 2.6a)
    appliedLearnings: jsonb("applied_learnings").default([]).notNull(),
    // CRDT sync metadata
    syncVersion: integer("sync_version").default(0).notNull(),
    lastSyncedAt: timestamp("last_synced_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
}, (table) => ({
    // Performance index for session context lookups (P0-2)
    workspaceIdx: index("idx_session_context_workspace").on(table.workspaceId, table.updatedAt),
}));
export const sessionContextRelations = relations(sessionContext, ({ one }) => ({
    user: one(user, {
        fields: [sessionContext.userId],
        references: [user.id],
    }),
}));
