import { sql } from "drizzle-orm";
import { index, jsonb, pgTable, text, timestamp, unique, uuid } from "drizzle-orm/pg-core";
/**
 * Scheduled Emails Table
 *
 * Durable store for time-delayed email sends (e.g. day-3 first_session nudge).
 * A row is "pending" while firedAt and cancelledAt are both NULL.
 *
 * Pattern: insert on trigger → poll every 60s → fire handler → mark firedAt
 * Cancellation: upstream event (e.g. first_session fires) → set cancelledAt
 *
 * EMAIL-04  -  Spec 2 Phase 3
 */
export const scheduledEmails = pgTable("scheduled_emails", {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id").notNull(),
    eventType: text("event_type").notNull(),
    scheduledAt: timestamp("scheduled_at", { withTimezone: true }).notNull(),
    firedAt: timestamp("fired_at", { withTimezone: true }),
    cancelledAt: timestamp("cancelled_at", { withTimezone: true }),
    payload: jsonb("payload"),
}, (t) => [
    unique("scheduled_emails_user_event_unique").on(t.userId, t.eventType),
    index("scheduled_emails_due_idx")
        .on(t.scheduledAt)
        .where(sql `${t.firedAt} IS NULL AND ${t.cancelledAt} IS NULL`),
]);
