// ESM imports fixed for Node.js v22+
/**
 * User Attribution Schema
 * Tracks marketing attribution for user acquisition
 */
import { relations } from "drizzle-orm";
import { index, json, pgTable, text, timestamp } from "drizzle-orm/pg-core";
import { nanoid } from "nanoid";
import { user } from "../postgres.js";
export const userAttributions = pgTable("user_attributions", {
    id: text("id")
        .primaryKey()
        .$defaultFn(() => nanoid()),
    userId: text("user_id")
        .notNull()
        .unique()
        .references(() => user.id, { onDelete: "cascade" }),
    source: text("source").notNull(), // 'google', 'facebook', 'direct', etc.
    campaignId: text("campaign_id"),
    fingerprint: text("fingerprint").notNull(),
    conversionData: json("conversion_data").$type(),
    utmParams: json("utm_params").$type(),
    referralCode: text("referral_code"),
    convertedAt: timestamp("converted_at"), // When user purchased subscription
    createdAt: timestamp("created_at").notNull().defaultNow(),
}, (table) => [
    index("user_attributions_user_id_idx").on(table.userId),
    index("user_attributions_fingerprint_idx").on(table.fingerprint),
    index("user_attributions_source_idx").on(table.source),
    index("user_attributions_created_at_idx").on(table.createdAt),
]);
export const userAttributionsRelations = relations(userAttributions, ({ one }) => ({
    user: one(user, {
        fields: [userAttributions.userId],
        references: [user.id],
    }),
}));
