// ESM imports fixed for Node.js v22+
/**
 * Credits Ledger Schema
 *
 * Tracks all credit transactions for the credit-based billing system.
 * Per pricing_spec_v3.md: Credits apply only to operations with real server-side compute cost.
 *
 * Transaction types:
 * - monthly_allowance: Monthly credit grant based on tier
 * - top_up: Purchased credit pack
 * - job_consumption: Credits consumed by a job
 * - refund: Credits returned (e.g., job failed)
 * - admin_adjustment: Manual adjustment by admin
 *
 * @module credits-ledger
 */
import { relations } from "drizzle-orm";
import { integer, jsonb, pgEnum, pgTable, text, timestamp, uniqueIndex } from "drizzle-orm/pg-core";
import { nanoid } from "nanoid";
import { organization, user } from "../postgres.js";
// Transaction type enum
export const creditTransactionTypeEnum = pgEnum("credit_transaction_type", [
    "monthly_allowance",
    "top_up",
    "job_consumption",
    "refund",
    "admin_adjustment",
]);
// Job type enum for credit consumption
export const creditJobTypeEnum = pgEnum("credit_job_type", [
    "deep_risk_sweep",
    "full_codebase_scan",
    "memory_sync",
    "synthesis",
    "layer3_personalization",
    "ai_refactor_plan",
    "fleet_analysis",
    "vitals_history",
]);
// Transaction status enum
export const creditTransactionStatusEnum = pgEnum("credit_transaction_status", [
    "pending", // Reserved but not yet finalized
    "completed", // Transaction finalized
    "failed", // Transaction failed
    "reversed", // Transaction reversed (refund)
]);
/**
 * Credits Ledger Table
 *
 * Every credit transaction is recorded here with running balance.
 * This is the source of truth for credit balance calculations.
 */
export const creditsLedger = pgTable("credits_ledger", {
    id: text("id")
        .primaryKey()
        .$defaultFn(() => nanoid()),
    userId: text("user_id").references(() => user.id, {
        onDelete: "cascade",
    }),
    organizationId: text("organization_id").references(() => organization.id, {
        onDelete: "cascade",
    }),
    // Credit transaction details
    credits: integer("credits").notNull(), // positive = add, negative = consume
    balanceAfter: integer("balance_after").notNull(), // Running balance after this transaction
    // Transaction metadata
    transactionType: creditTransactionTypeEnum("transaction_type").notNull(),
    status: creditTransactionStatusEnum("status").notNull().default("completed"),
    // Job-specific fields (for job_consumption type)
    jobType: creditJobTypeEnum("job_type"),
    jobId: text("job_id"), // Reference to the actual job (e.g., analysis ID)
    estimatedCredits: integer("estimated_credits"), // Original estimate before job ran
    // Cost tracking (for internal analysis, per spec Phase 1)
    estimatedCostCents: integer("estimated_cost_cents"), // Estimated internal cost
    actualCostCents: integer("actual_cost_cents"), // Actual internal cost
    tokensUsed: integer("tokens_used"), // LLM tokens if applicable
    graphNodes: integer("graph_nodes"), // Graph size if applicable
    fileCount: integer("file_count"), // File count if applicable
    // Stripe integration (for top-ups)
    stripePaymentIntentId: text("stripe_payment_intent_id"),
    stripeCheckoutSessionId: text("stripe_checkout_session_id"),
    // Top-up pack reference
    topupId: text("topup_id"), // Reference to credit_topups table
    // Billing period tracking
    billingPeriodStart: timestamp("billing_period_start"),
    billingPeriodEnd: timestamp("billing_period_end"),
    // Additional metadata
    metadata: jsonb("metadata").default({}),
    // Timestamps
    createdAt: timestamp("created_at").defaultNow().notNull(),
    finalizedAt: timestamp("finalized_at"),
}, (table) => ({
    // Indexes for common queries
    userIdIdx: uniqueIndex("idx_credits_ledger_user_id").on(table.userId),
    orgIdIdx: uniqueIndex("idx_credits_ledger_org_id").on(table.organizationId),
    transactionTypeIdx: uniqueIndex("idx_credits_ledger_transaction_type").on(table.transactionType),
    createdAtIdx: uniqueIndex("idx_credits_ledger_created_at").on(table.createdAt),
    billingPeriodIdx: uniqueIndex("idx_credits_ledger_billing_period").on(table.userId, table.billingPeriodStart),
    stripePaymentIdx: uniqueIndex("idx_credits_ledger_stripe_payment").on(table.stripePaymentIntentId),
}));
/**
 * Relations for credits ledger
 */
export const creditsLedgerRelations = relations(creditsLedger, ({ one }) => ({
    user: one(user, {
        fields: [creditsLedger.userId],
        references: [user.id],
    }),
    organization: one(organization, {
        fields: [creditsLedger.organizationId],
        references: [organization.id],
    }),
}));
