// ESM imports fixed for Node.js v22+
/**
 * Fingerprints - Workspace architecture fingerprint storage
 *
 * Facts-first, policy-aware, strict-schema fingerprint storage.
 *
 * SECURITY INVARIANTS:
 * - Never store raw manifests/lockfiles/SBOMs
 * - Only validated Facts and derived hashes are persisted
 * - Minimal mode: dependencies.inventory must be empty
 * - Strict-private with emitComponentNames=false: only hashed component IDs (cid_...)
 */
import { relations } from "drizzle-orm";
import { index, jsonb, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";
import { user } from "../postgres.js";
/**
 * Fingerprints table - Stores workspace architecture fingerprints
 */
export const fingerprints = pgTable("fingerprints", {
    id: uuid("id").primaryKey().defaultRandom(),
    // Ownership - scoped to user for tenant isolation
    userId: text("user_id")
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    // Workspace reference - logical workspace within user scope
    workspaceId: uuid("workspace_id").notNull(),
    workspaceKey: text("workspace_key").notNull(), // Original key for lookup
    // Policy at time of fingerprint (immutable record)
    policy: jsonb("policy").$type().notNull(),
    // Scan metadata
    scan: jsonb("scan").$type().notNull(),
    // Computed hashes
    driftFull: text("drift_full").notNull(), // SHA-256 full (64 hex chars)
    driftTruncated: text("drift_truncated").notNull(), // Truncated to 32 chars for transport
    similarity64: text("similarity_64"), // SimHash-64 (16 hex chars), null if not enabled
    similarityAlg: text("similarity_alg"), // "simhash64-v1" if similarity enabled
    // Facts storage level
    factsStored: text("facts_stored").notNull().default("summary"), // "none" | "summary" | "full"
    // Timestamps
    receivedAt: timestamp("received_at").notNull(),
    createdAt: timestamp("created_at").defaultNow().notNull(),
}, (table) => [
    // Index for workspace lookups (most common query pattern)
    index("fingerprints_workspace_id_idx").on(table.workspaceId),
    // Index for user-scoped queries
    index("fingerprints_user_id_idx").on(table.userId),
    // Composite index for latest fingerprint lookup
    index("fingerprints_workspace_received_idx").on(table.workspaceId, table.receivedAt),
]);
// Relations
export const fingerprintsRelations = relations(fingerprints, ({ one }) => ({
    user: one(user, {
        fields: [fingerprints.userId],
        references: [user.id],
    }),
}));
