import { index, json, pgEnum, pgTable, text, timestamp } from "drizzle-orm/pg-core";
import { nanoid } from "nanoid";
/**
 * Saga status enum
 */
export const sagaStatusEnum = pgEnum("saga_status", [
    "pending",
    "running",
    "completed",
    "failed",
    "compensating",
    "compensated",
]);
/**
 * Saga step status enum
 */
export const sagaStepStatusEnum = pgEnum("saga_step_status", [
    "pending",
    "running",
    "completed",
    "failed",
    "compensated",
    "skipped",
]);
/**
 * Saga instances table - tracks multi-step workflow execution
 */
export const sagas = pgTable("sagas", {
    id: text("id")
        .primaryKey()
        .$defaultFn(() => nanoid()),
    sagaId: text("saga_id").notNull().unique(),
    sagaType: text("saga_type").notNull(),
    status: sagaStatusEnum("status").notNull().default("pending"),
    context: json("context").$type().notNull(),
    steps: json("steps")
        .$type()
        .notNull(),
    error: text("error"),
    retryCount: text("retry_count").notNull().default("0"),
    maxRetries: text("max_retries").notNull().default("3"),
    startedAt: timestamp("started_at").notNull().defaultNow(),
    completedAt: timestamp("completed_at"),
    failedAt: timestamp("failed_at"),
    createdAt: timestamp("created_at").notNull().defaultNow(),
    updatedAt: timestamp("updated_at").notNull().defaultNow(),
}, (table) => [
    index("sagas_saga_id_idx").on(table.sagaId),
    index("sagas_saga_type_idx").on(table.sagaType),
    index("sagas_status_idx").on(table.status),
    index("sagas_started_at_idx").on(table.startedAt),
    index("sagas_created_at_idx").on(table.createdAt),
]);
