// Enums
export const purchaseTypeEnum = pgEnum("PurchaseType", ["SUBSCRIPTION", "ONE_TIME"]);

// Add new enums for Vreko
export const subscriptionStatusEnum = pgEnum("subscription_status", [
	"active",
	"canceled",
	"past_due",
	"trialing",
	"paused",
]);

export const planTypeEnum = pgEnum("plan_type", ["free", "pro", "team", "enterprise"]);

// Tables
export const user = pgTable("user", {
	id: varchar("id", { length: 255 })
		.$defaultFn(() => nanoid())
		.primaryKey(),
	name: text("name").notNull(),
	email: text("email").notNull().unique(),
	emailVerified: boolean("emailVerified").notNull().default(false),
	image: text("image"),
	createdAt: timestamp("createdAt").notNull().defaultNow(),
	updatedAt: timestamp("updatedAt").notNull().defaultNow(),
	username: text("username").unique(),
	displayUsername: text("displayUsername").unique(), // Better Auth username plugin
	role: text("role"),
	banned: boolean("banned"),
	banReason: text("banReason"),
	banExpires: timestamp("banExpires"),
	onboardingComplete: boolean("onboardingComplete").default(false).notNull(),
	paymentsCustomerId: text("paymentsCustomerId"),
	locale: text("locale"),
	totalSnapshots: integer("totalSnapshots").default(0).notNull(),
	totalRecoveries: integer("totalRecoveries").default(0).notNull(),
	subscriptionTier: planTypeEnum("subscription_tier").default("free"), // Add subscription tier field
	tierExpiresAt: timestamp("tier_expires_at", { withTimezone: true }), // Timed admin tier grants
	twoFactorEnabled: boolean("twoFactorEnabled").default(false), // Required by Better Auth twoFactor plugin
	deviceFingerprint: text("deviceFingerprint"), // Added for fraud prevention
	// Abuse Defense Phase 1 fields
	normalizedEmail: varchar("normalized_email", { length: 255 }), // For email deduplication
	concurrentDeviceCount: integer("concurrent_device_count").default(0).notNull(), // Active devices
	maxObservedDevices: integer("max_observed_devices").default(0).notNull(), // High watermark
	// Pioneer Program
	pioneer: boolean("pioneer").default(false),
	pioneerCohort: integer("pioneer_cohort"),
	pioneerActivatedAt: timestamp("pioneer_activated_at", { withTimezone: true }),
});

export const session = pgTable(
	"session",
	{
		id: varchar("id", { length: 255 })
			.$defaultFn(() => nanoid())
			.primaryKey(),
		expiresAt: timestamp("expiresAt").notNull(),
		ipAddress: text("ipAddress"),
		userAgent: text("userAgent"),
		userId: text("userId")
			.notNull()
			.references(() => user.id, { onDelete: "cascade" }),
		impersonatedBy: text("impersonatedBy"),
		activeOrganizationId: text("activeOrganizationId"),
		token: text("token").notNull(),
		createdAt: timestamp("createdAt").notNull(),
		updatedAt: timestamp("updatedAt").notNull(),
	},

	(table) => [uniqueIndex("session_token_idx").on(table.token)],
);

export const account = pgTable("account", {
	id: varchar("id", { length: 255 })
		.$defaultFn(() => nanoid())
		.primaryKey(),
	accountId: text("accountId").notNull(),
	providerId: text("providerId").notNull(),
	userId: text("userId")
		.notNull()
		.references(() => user.id, { onDelete: "cascade" }),
	accessToken: text("accessToken"),
	refreshToken: text("refreshToken"),
	idToken: text("idToken"),
	expiresAt: timestamp("expiresAt"),
	password: text("password"),
	accessTokenExpiresAt: timestamp("accessTokenExpiresAt"),
	refreshTokenExpiresAt: timestamp("refreshTokenExpiresAt"),
	scope: text("scope"),
	createdAt: timestamp("createdAt").notNull(),
	updatedAt: timestamp("updatedAt").notNull(),
});

export const verification = pgTable("verification", {
	id: varchar("id", { length: 255 })
		.$defaultFn(() => nanoid())
		.primaryKey(),
	identifier: text("identifier").notNull(),
	value: text("value").notNull(),
	expiresAt: timestamp("expiresAt").notNull(),
	createdAt: timestamp("createdAt"),
	updatedAt: timestamp("updatedAt"),
});

export const passkey = pgTable("passkey", {
	id: varchar("id", { length: 255 })
		.$defaultFn(() => nanoid())
		.primaryKey(),
	name: text("name"),
	publicKey: text("publicKey").notNull(),
	userId: text("userId")
		.notNull()
		.references(() => user.id, { onDelete: "cascade" }),
	credentialID: text("credentialID").notNull(),
	counter: integer("counter").notNull(),
	deviceType: text("deviceType").notNull(),
	backedUp: boolean("backedUp").notNull(),
	transports: text("transports"),
	createdAt: timestamp("createdAt"),
});

export const twoFactor = pgTable("twoFactor", {
	id: varchar("id", { length: 255 })
		.$defaultFn(() => nanoid())
		.primaryKey(),
	secret: text("secret").notNull(),
	backupCodes: text("backupCodes").notNull(),
	userId: text("userId")
		.notNull()
		.references(() => user.id, { onDelete: "cascade" }),
});

// Better Auth rate limiting table
// Note: lastRequest uses default string mode for Better Auth compatibility
export const rateLimit = pgTable("rateLimit", {
	id: varchar("id", { length: 255 })
		.$defaultFn(() => nanoid())
		.primaryKey(),
	key: text("key").notNull(),
	count: integer("count").notNull().default(0),
	lastRequest: bigint("lastRequest", { mode: "number" }).notNull(),
});

// Better Auth JWKS table (for JWT plugin)
