export const emailCategoryEnum = pgEnum("email_category", [
	"authentication",
	"onboarding",
	"product",
	"billing",
	"marketing",
]);

export const emailStatusEnum = pgEnum("email_status", [
	"pending",
	"sent",
	"delivered",
	"opened",
	"clicked",
	"bounced",
	"failed",
]);

// Email deliveries table
export const emailDeliveries = pgTable(
	"email_deliveries",
	{
		id: text("id")
			.primaryKey()
			.$defaultFn(() => nanoid()),
		userId: text("user_id")
			.notNull()
			.references(() => user.id, { onDelete: "cascade" }),
		templateId: text("template_id").notNull(),
		category: emailCategoryEnum("category").notNull(),
		provider: text("provider").notNull(), // 'resend' | 'hubspot'

		// Delivery details
		recipientEmail: text("recipient_email").notNull(),
		subject: text("subject").notNull(),
		status: emailStatusEnum("status").notNull().default("pending"),

		// Provider-specific IDs
		resendEmailId: text("resend_email_id"),
		hubspotEngagementId: text("hubspot_engagement_id"),

		// Timestamps
		sentAt: timestamp("sent_at"),
		deliveredAt: timestamp("delivered_at"),
		openedAt: timestamp("opened_at"),
		clickedAt: timestamp("clicked_at"),
		failedAt: timestamp("failed_at"),

		// Error tracking
		errorMessage: text("error_message"),
		retryCount: integer("retry_count").notNull().default(0),

		// Context
		metadata: json("metadata").$type<Record<string, unknown>>(),

		createdAt: timestamp("created_at").notNull().defaultNow(),
		updatedAt: timestamp("updated_at").notNull().defaultNow(),
	},
	(table) => [
		index("email_deliveries_user_id_idx").on(table.userId),
		index("email_deliveries_status_idx").on(table.status),
		index("email_deliveries_sent_at_idx").on(table.sentAt),
		index("email_deliveries_category_idx").on(table.category),
		index("email_deliveries_template_id_idx").on(table.templateId),
	],
);

// Email preferences table
export const emailPreferences = pgTable(
	"email_preferences",
	{
		id: text("id")
			.primaryKey()
			.$defaultFn(() => nanoid()),
		userId: text("user_id")
			.notNull()
			.unique()
			.references(() => user.id, { onDelete: "cascade" }),

		// Global opt-out
		unsubscribedAll: boolean("unsubscribed_all").notNull().default(false),
		unsubscribedAt: timestamp("unsubscribed_at"),
		unsubscribeSource: text("unsubscribe_source"), // 'resend' | 'hubspot' | 'app'

		// Category-specific preferences
		enabledCategories: json("enabled_categories").$type<string[]>().default(["authentication", "billing"]),

		// Digest preferences
		digestFrequency: text("digest_frequency").notNull().default("weekly"), // 'daily' | 'weekly' | 'never'
		digestDay: integer("digest_day"), // 0-6 for day of week
		digestTime: text("digest_time").notNull().default("09:00"), // HH:MM format

		// HubSpot sync
		hubspotContactId: text("hubspot_contact_id"),
		lastSyncedToHubspot: timestamp("last_synced_to_hubspot"),

		createdAt: timestamp("created_at").notNull().defaultNow(),
		updatedAt: timestamp("updated_at").notNull().defaultNow(),
	},
	(table) => [
		index("email_preferences_user_id_idx").on(table.userId),
		index("email_preferences_hubspot_contact_id_idx").on(table.hubspotContactId),
	],
);

