// ESM imports fixed for Node.js v22+
/**
 * MCP Persistent Storage Schema
 *
 * Drizzle ORM schema for MCP observations, tool invocations, and extension sync state.
 * These tables persist data from the MCP bridge to prevent data loss on server restart.
 *
 * Tables:
 * - mcp_observations: Stores observations from VSCode extension
 * - mcp_tool_invocations: Tracks tool calls for billing and analytics
 * - extension_sync_state: Manages offline-first sync state
 */
import { relations, sql } from "drizzle-orm";
import { boolean, index, integer, jsonb, pgEnum, pgTable, text, timestamp, unique, uuid } from "drizzle-orm/pg-core";
import { user } from "../postgres.js";
// ============================================================================
// Enums
// ============================================================================
export const observationTypeEnum = pgEnum("observation_type", ["risk", "pattern", "suggestion", "warning", "progress"]);
export const observationSeverityEnum = pgEnum("observation_severity", ["low", "medium", "high", "critical"]);
export const observationSourceEnum = pgEnum("observation_source", ["extension", "mcp-server", "dashboard", "api"]);
export const invocationTypeEnum = pgEnum("invocation_type", ["inline-edit", "chat", "command", "suggestion"]);
export const invocationStatusEnum = pgEnum("invocation_status", ["pending", "success", "error", "timeout"]);
export const deviceTypeEnum = pgEnum("device_type", ["vscode", "cursor", "windsurf", "cli"]);
export const conflictStrategyEnum = pgEnum("conflict_resolution_strategy", ["server-wins", "client-wins", "merge"]);
// ============================================================================
// MCP Observations Table
// ============================================================================
export const mcpObservations = pgTable("mcp_observations", {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: text("workspace_id").notNull(),
    userId: text("user_id").references(() => user.id, { onDelete: "cascade" }),
    // Observation content
    type: observationTypeEnum("type").notNull(),
    severity: observationSeverityEnum("severity"),
    message: text("message").notNull(),
    context: jsonb("context").default({}),
    filePath: text("file_path"),
    lineNumber: integer("line_number"),
    // Source tracking
    source: observationSourceEnum("source").default("extension"),
    toolName: text("tool_name"),
    // Processing status
    processed: boolean("processed").default(false),
    processedAt: timestamp("processed_at", { withTimezone: true }),
    // Idempotency
    idempotencyKey: text("idempotency_key").unique(),
    // CRDT sync metadata
    syncVersion: integer("sync_version").default(0),
    deviceId: text("device_id"),
    // Timestamps
    observedAt: timestamp("observed_at", { withTimezone: true }).defaultNow(),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
}, (table) => ({
    // Performance indexes
    workspaceIdx: index("idx_mcp_observations_workspace").on(table.workspaceId, table.createdAt),
    userIdx: index("idx_mcp_observations_user").on(table.userId, table.createdAt),
    typeIdx: index("idx_mcp_observations_type")
        .on(table.type, table.createdAt)
        .where(sql `${table.processed} = false`),
    idempotencyIdx: index("idx_mcp_observations_idempotency")
        .on(table.idempotencyKey)
        .where(sql `${table.idempotencyKey} IS NOT NULL`),
    syncIdx: index("idx_mcp_observations_sync").on(table.deviceId, table.syncVersion),
    contextIdx: index("idx_mcp_observations_context").using("gin", table.context),
}));
export const mcpObservationsRelations = relations(mcpObservations, ({ one }) => ({
    user: one(user, {
        fields: [mcpObservations.userId],
        references: [user.id],
    }),
}));
// ============================================================================
// MCP Tool Invocations Table
// ============================================================================
export const mcpToolInvocations = pgTable("mcp_tool_invocations", {
    id: uuid("id").primaryKey().defaultRandom(),
    workspaceId: text("workspace_id").notNull(),
    userId: text("user_id").references(() => user.id, { onDelete: "cascade" }),
    // Invocation details
    toolName: text("tool_name").notNull(),
    toolVersion: text("tool_version"),
    invocationType: invocationTypeEnum("invocation_type"),
    // Request/Response tracking
    requestPayload: jsonb("request_payload"),
    responsePayload: jsonb("response_payload"),
    status: invocationStatusEnum("status"),
    errorMessage: text("error_message"),
    // Performance metrics
    startedAt: timestamp("started_at", { withTimezone: true }).defaultNow(),
    completedAt: timestamp("completed_at", { withTimezone: true }),
    durationMs: integer("duration_ms"),
    // Token usage
    inputTokens: integer("input_tokens").default(0),
    outputTokens: integer("output_tokens").default(0),
    // Idempotency
    idempotencyKey: text("idempotency_key").unique(),
    // Source tracking
    source: text("source").default("extension"),
    sessionId: text("session_id"),
    // Timestamps
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
}, (table) => ({
    // Performance indexes
    workspaceIdx: index("idx_mcp_invocations_workspace").on(table.workspaceId, table.createdAt),
    userIdx: index("idx_mcp_invocations_user").on(table.userId, table.createdAt),
    toolIdx: index("idx_mcp_invocations_tool").on(table.toolName, table.createdAt),
    statusIdx: index("idx_mcp_invocations_status")
        .on(table.status, table.createdAt)
        .where(sql `${table.status} = 'pending'`),
    sessionIdx: index("idx_mcp_invocations_session").on(table.sessionId, table.createdAt),
    billingIdx: index("idx_mcp_invocations_billing")
        .on(table.userId, table.createdAt)
        .where(sql `${table.status} = 'success'`),
}));
export const mcpToolInvocationsRelations = relations(mcpToolInvocations, ({ one }) => ({
    user: one(user, {
        fields: [mcpToolInvocations.userId],
        references: [user.id],
    }),
}));
// ============================================================================
// Extension Sync State Table
// ============================================================================
export const extensionSyncState = pgTable("extension_sync_state", {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    workspaceId: text("workspace_id").notNull(),
    deviceId: text("device_id").notNull(),
    // Sync metadata
    lastSyncAt: timestamp("last_sync_at", { withTimezone: true }),
    syncVersion: integer("sync_version").default(0),
    // Device info
    deviceType: deviceTypeEnum("device_type"),
    deviceName: text("device_name"),
    // Sync window
    syncWindowStart: timestamp("sync_window_start", { withTimezone: true }),
    syncWindowEnd: timestamp("sync_window_end", { withTimezone: true }),
    // Pending changes
    pendingChangesCount: integer("pending_changes_count").default(0),
    pendingChanges: jsonb("pending_changes").default([]),
    // Conflict resolution
    lastConflictAt: timestamp("last_conflict_at", { withTimezone: true }),
    conflictResolutionStrategy: conflictStrategyEnum("conflict_resolution_strategy").default("server-wins"),
    // Health check
    lastHeartbeatAt: timestamp("last_heartbeat_at", { withTimezone: true }),
    isOnline: boolean("is_online").default(true),
    // Timestamps
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
}, (table) => ({
    // Unique constraint: one sync state per user/workspace/device
    uniqueUserWorkspaceDevice: unique().on(table.userId, table.workspaceId, table.deviceId),
    // Performance indexes
    userIdx: index("idx_sync_state_user").on(table.userId, table.lastSyncAt),
    workspaceIdx: index("idx_sync_state_workspace").on(table.workspaceId, table.lastSyncAt),
    pendingIdx: index("idx_sync_state_pending")
        .on(table.userId, table.pendingChangesCount)
        .where(sql `${table.pendingChangesCount} > 0`),
    heartbeatIdx: index("idx_sync_state_heartbeat").on(table.lastHeartbeatAt).where(sql `${table.isOnline} = true`),
}));
export const extensionSyncStateRelations = relations(extensionSyncState, ({ one }) => ({
    user: one(user, {
        fields: [extensionSyncState.userId],
        references: [user.id],
    }),
}));
