// ESM imports fixed for Node.js v22+
import { index, integer, pgTable, text, timestamp } from "drizzle-orm/pg-core";
import { user } from "../postgres.js";
/**
 * Better Auth Device Authorization Grant (RFC 8628)
 * OAuth 2.0 device flow for headless/CLI authentication
 */
export const deviceCode = pgTable("device_code", {
    id: text("id").primaryKey(),
    deviceCode: text("device_code").notNull(),
    userCode: text("user_code").notNull(),
    userId: text("user_id").references(() => user.id, { onDelete: "cascade" }),
    expiresAt: timestamp("expires_at").notNull(),
    status: text("status").notNull(), // "pending" | "approved" | "denied" | "expired"
    lastPolledAt: timestamp("last_polled_at"),
    pollingInterval: integer("polling_interval"),
    clientId: text("client_id"),
    scope: text("scope"),
    // Reason for denial  -  null unless status is "denied"
    deniedReason: text("denied_reason"),
}, (table) => ({
    deviceCodeIdx: index("device_code_device_code_idx").on(table.deviceCode),
    userCodeIdx: index("device_code_user_code_idx").on(table.userCode),
    userIdIdx: index("device_code_user_id_idx").on(table.userId),
}));
