// ESM imports fixed for Node.js v22+
/**
 * Credit Top-Ups Schema
 *
 * Tracks purchased credit packs for Pro and Team tiers.
 * Per pricing_spec_v3.md:
 *
 * | Pack | Price | Per-Credit | Savings |
 * |------|-------|------------|---------|
 * | 50 credits  | $5  | $0.10 |  -       |
 * | 100 credits | $9  | $0.09 | 10%    |
 * | 250 credits | $20 | $0.08 | 20%    |
 *
 * Top-ups do not expire. They're consumed after the monthly included allowance is depleted.
 * Free tier users cannot purchase top-ups (must upgrade to Pro).
 *
 * @module credit-topups
 */
import { relations } from "drizzle-orm";
import { integer, jsonb, pgEnum, pgTable, text, timestamp, uniqueIndex } from "drizzle-orm/pg-core";
import { nanoid } from "nanoid";
import { organization, user } from "../postgres.js";
// Top-up status enum
export const topupStatusEnum = pgEnum("topup_status", [
    "pending", // Payment initiated but not completed
    "completed", // Payment successful, credits added
    "failed", // Payment failed
    "refunded", // Payment refunded, credits removed
    "canceled", // User canceled before payment
]);
// Top-up pack sizes (per spec)
export const TOPUP_PACKS = {
    50: { priceCents: 500, perCredit: 0.1, savings: 0 },
    100: { priceCents: 900, perCredit: 0.09, savings: 10 },
    250: { priceCents: 2000, perCredit: 0.08, savings: 20 },
};
/**
 * Credit Top-Ups Table
 *
 * Tracks all credit pack purchases.
 */
export const creditTopups = pgTable("credit_topups", {
    id: text("id")
        .primaryKey()
        .$defaultFn(() => nanoid()),
    userId: text("user_id").references(() => user.id, {
        onDelete: "cascade",
    }),
    organizationId: text("organization_id").references(() => organization.id, {
        onDelete: "cascade",
    }),
    // Pack details
    packSize: integer("pack_size").notNull(), // 50, 100, or 250
    priceCents: integer("price_cents").notNull(), // 500, 900, or 2000
    // Stripe integration
    stripePaymentIntentId: text("stripe_payment_intent_id"),
    stripeCheckoutSessionId: text("stripe_checkout_session_id"),
    stripeCustomerId: text("stripe_customer_id"),
    // Status tracking
    status: topupStatusEnum("status").notNull().default("pending"),
    // Ledger reference (credits added via ledger)
    ledgerTransactionId: text("ledger_transaction_id"), // Reference to credits_ledger entry
    // Additional metadata
    metadata: jsonb("metadata").default({}),
    // Timestamps
    createdAt: timestamp("created_at").defaultNow().notNull(),
    completedAt: timestamp("completed_at"),
    refundedAt: timestamp("refunded_at"),
}, (table) => ({
    // Indexes
    userIdIdx: uniqueIndex("idx_credit_topups_user_id").on(table.userId),
    orgIdIdx: uniqueIndex("idx_credit_topups_org_id").on(table.organizationId),
    statusIdx: uniqueIndex("idx_credit_topups_status").on(table.status),
    stripePaymentIdx: uniqueIndex("idx_credit_topups_stripe_payment").on(table.stripePaymentIntentId),
    stripeCheckoutIdx: uniqueIndex("idx_credit_topups_stripe_checkout").on(table.stripeCheckoutSessionId),
}));
/**
 * Relations for credit top-ups
 */
export const creditTopupsRelations = relations(creditTopups, ({ one }) => ({
    user: one(user, {
        fields: [creditTopups.userId],
        references: [user.id],
    }),
    organization: one(organization, {
        fields: [creditTopups.organizationId],
        references: [organization.id],
    }),
}));
/**
 * Helper function to get pack details
 */
export function getTopupPackDetails(packSize) {
    return TOPUP_PACKS[packSize];
}
/**
 * Helper function to validate pack size
 */
export function isValidPackSize(size) {
    return size in TOPUP_PACKS;
}
