// ESM imports fixed for Node.js v22+
import { relations, sql } from "drizzle-orm";
import { check, integer, jsonb, numeric, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";
import { user } from "../postgres.js";
// =============================================================================
// SCHEMA DEFINITION
// =============================================================================
/**
 * User Detection Capabilities - Learned improvements from user behavior
 *
 * Privacy: No code content stored, only pattern keys and numerical thresholds (C-006)
 *
 * This table stores per-user learned improvements to AI detection:
 * - False positive patterns (user proceeded after warning)
 * - Custom risk indicators (user-specific patterns)
 * - Threshold overrides (personalized sensitivity)
 * - Accuracy tracking (per-tool detection accuracy)
 *
 * Tier gating:
 * - Free: Basic false positive learning only
 * - Pro: Full customization (thresholds, risk indicators, tool-specific accuracy)
 * - Enterprise: Team-wide capability sharing (future)
 */
export const userDetectionCapabilities = pgTable("user_detection_capabilities", {
    id: uuid("id").primaryKey().defaultRandom(),
    userId: text("user_id")
        .notNull()
        .unique() // One capability record per user
        .references(() => user.id, { onDelete: "cascade" }),
    // ===================
    // LEARNED IMPROVEMENTS
    // ===================
    /** Custom risk indicators learned from user behavior (Pro+) */
    customRiskIndicators: jsonb("custom_risk_indicators").$type().default([]),
    /** False positive patterns from user proceed actions (Free+) */
    falsePositivePatterns: jsonb("false_positive_patterns").$type().default([]),
    /** User-specific threshold overrides (Pro+) */
    thresholdOverrides: jsonb("threshold_overrides").$type().default({}),
    // ===================
    // ACCURACY TRACKING
    // ===================
    /** Total detections analyzed for this user */
    totalDetectionsAnalyzed: integer("total_detections_analyzed").default(0),
    /** Overall accuracy score (0.0000-1.0000) */
    accuracyScore: numeric("accuracy_score", { precision: 5, scale: 4 }),
    /** Tool-specific accuracy (e.g., { cursor: 0.92, copilot: 0.87 }) (Pro+) */
    toolAccuracy: jsonb("tool_accuracy").$type().default({}),
    // ===================
    // TIER GATING
    // ===================
    /** User's current tier (determines which capabilities are active) */
    tier: text("tier").$type().default("free"),
    // ===================
    // VERSIONING
    // ===================
    /** Optimistic locking version (incremented on each update) */
    version: integer("version").default(1),
    /** Last time capabilities were updated */
    lastUpdated: timestamp("last_updated").defaultNow(),
    /** When this record was created */
    createdAt: timestamp("created_at").defaultNow().notNull(),
}, (table) => [
    // Accuracy score must be between 0 and 1
    check("accuracy_score_range", sql `${table.accuracyScore} >= 0 AND ${table.accuracyScore} <= 1`),
    // Tier must be valid
    check("tier_valid", sql `${table.tier} IN ('free', 'pro', 'enterprise')`),
]);
// =============================================================================
// RELATIONS
// =============================================================================
export const userDetectionCapabilitiesRelations = relations(userDetectionCapabilities, ({ one }) => ({
    user: one(user, {
        fields: [userDetectionCapabilities.userId],
        references: [user.id],
    }),
}));
