// ESM imports fixed for Node.js v22+
import { relations } from "drizzle-orm";
import { boolean, customType, decimal, index, integer, pgTable, text, timestamp, uniqueIndex, } from "drizzle-orm/pg-core";
import { user } from "../postgres.js";
/**
 * Custom vector type for pgvector extension
 * Stores 256-dimensional float vectors for similarity search
 */
const vector256 = customType({
    dataType() {
        return "vector(256)";
    },
    toDriver(value) {
        return `[${value.join(",")}]`;
    },
    fromDriver(value) {
        // Parse vector string like "[0.1,0.2,...]" to array
        return value
            .replace(/[[\]]/g, "")
            .split(",")
            .map((v) => Number.parseFloat(v));
    },
});
/**
 * Patterns - Code pattern library with vector similarity search
 *
 * Stores pattern signatures with pgvector embeddings for fast similarity matching.
 * Supports both local (per-user) and global (anonymized community) patterns.
 *
 * REQUIRES: pgvector extension enabled in database (Migration 0011)
 */
export const patterns = pgTable("patterns", {
    id: text("id")
        .primaryKey()
        .$defaultFn(() => crypto.randomUUID()),
    // Optional ownership (null = global pattern)
    userId: text("user_id").references(() => user.id, { onDelete: "cascade" }),
    // Pattern identification
    patternSignature: text("pattern_signature").unique().notNull(), // AST-based hash
    // Vector embedding for similarity search (256 dimensions)
    // P0-1: Cast to vector(256) via migration 0011_enable_pgvector.sql
    embedding: vector256("embedding"),
    // Classification
    patternType: text("pattern_type").notNull(), // 'dangerous', 'beneficial', 'neutral'
    toolAffinity: text("tool_affinity").array(), // ['cursor', 'copilot', ...]
    fileTypes: text("file_types").array(), // ['.ts', '.tsx', ...]
    // Success metrics
    occurrenceCount: integer("occurrence_count").default(1).notNull(),
    successRate: decimal("success_rate", { precision: 4, scale: 3 }), // 0.000-1.000
    // Timestamps
    firstSeenAt: timestamp("first_seen_at").defaultNow().notNull(),
    lastSeenAt: timestamp("last_seen_at").defaultNow().notNull(),
    // Global vs local
    isGlobal: boolean("is_global").default(false).notNull(),
}, (table) => [
    // Unique pattern signature
    uniqueIndex("patterns_signature_idx").on(table.patternSignature),
    // Query by user
    index("patterns_user_idx").on(table.userId),
    // Query by type
    index("patterns_type_idx").on(table.patternType),
    // Query global patterns
    index("patterns_global_idx").on(table.isGlobal),
    // P0-1: HNSW index for vector similarity search (created in migration 0011)
    // CREATE INDEX patterns_embedding_hnsw_idx ON patterns USING hnsw (embedding vector_cosine_ops) WITH (m = 16, ef_construction = 64);
]);
export const patternsRelations = relations(patterns, ({ one }) => ({
    user: one(user, {
        fields: [patterns.userId],
        references: [user.id],
    }),
}));
