// ESM imports fixed for Node.js v22+
/**
 * Task-First Architecture Database Schema
 *
 * Tasks are the first-class entity in Vreko with stable IDs, display names,
 * accumulated state, and ceremonies. Sessions are daemon connections that come
 * and go underneath a Task.
 *
 * Storage Notes:
 * - Local daemon uses SQLite in WAL mode at ~/.vreko/projects/<project-slug>/tasks.db
 * - Server-side cloud sync uses PostgreSQL (this schema)
 *
 * Key Design Principles:
 * - Derived counters are NEVER stored - always computed from accumulated state
 * - All writes are append-only (events, files, learnings)
 * - Content-hash deduplication for learnings
 * - Quality gates can block ceremony completion
 *
 * @see /devagents/plans/Task_Connonical_impl.md
 * @module platform/db/schema/vreko/tasks
 */
import { relations, sql } from "drizzle-orm";
import { boolean, index, integer, pgEnum, pgTable, text, timestamp, uniqueIndex } from "drizzle-orm/pg-core";
import { user } from "../postgres.js";
// =============================================================================
// ENUMS
// =============================================================================
/**
 * Task status enum
 *
 * State transitions:
 * - created → active
 * - active → completed, abandoned, failed, ceremony_blocked, auto-ended
 * - ceremony_blocked → active (fix issues), completed (force:true)
 * - completed, abandoned, failed, auto-ended → (terminal)
 */
export const taskStatusEnum = pgEnum("task_status", [
    "created",
    "active",
    "completed",
    "abandoned",
    "failed",
    "auto-ended",
    "ceremony_blocked",
]);
/**
 * Task outcome enum (for vreko_end)
 */
export const taskOutcomeEnum = pgEnum("task_outcome", ["completed", "abandoned", "failed"]);
/**
 * Task event type enum
 */
export const taskEventTypeEnum = pgEnum("task_event_type", [
    "task_created",
    "task_resumed",
    "task_ended",
    "learning_captured",
    "pulse_recorded",
    "file_changed",
    "session_connected",
    "session_disconnected",
    "ceremony_blocked",
    "ceremony_completed",
]);
/**
 * File action enum
 */
export const fileActionEnum = pgEnum("file_action", ["added", "modified", "deleted"]);
/**
 * Learning category enum
 */
export const learningCategoryEnum = pgEnum("learning_category", [
    "pattern",
    "gotcha",
    "decision",
    "convention",
    "discovery",
]);
/**
 * Learning confidence enum
 */
export const learningConfidenceEnum = pgEnum("learning_confidence", ["low", "medium", "high"]);
/**
 * Migration source enum
 */
export const migrationSourceEnum = pgEnum("migration_source", ["active_session", "completed_session"]);
// =============================================================================
// TASKS TABLE
// =============================================================================
/**
 * Tasks table - the first-class entity in Vreko
 *
 * Privacy: Metadata only, no user code content (C-006)
 */
export const tasks = pgTable("tasks", {
    // Primary key - monotonic integer
    id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
    // Deterministic kebab-case identifier for matching
    slug: text("slug").notNull().unique(),
    // Human-readable task name provided by LLM
    name: text("name").notNull(),
    // Current status
    status: taskStatusEnum("status").notNull().default("created"),
    // Outcome when task was closed
    outcome: taskOutcomeEnum("outcome"),
    // User who owns this task
    userId: text("user_id")
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    // Workspace identifier (hashed)
    workspaceId: text("workspace_id").notNull(),
    // Timestamps
    createdAt: timestamp("created_at").notNull().defaultNow(),
    updatedAt: timestamp("updated_at").notNull().defaultNow(),
    closedAt: timestamp("closed_at"),
    // JSON-serialized ceremony object
    ceremonyJson: text("ceremony_json"),
    // Task lineage - references another task this continues from
    continuesFrom: integer("continues_from"), // Self-reference handled by application layer
    // Migration tracking
    migrationSource: migrationSourceEnum("migration_source"),
    originalSessionId: text("original_session_id"), // For correlation with legacy sessions
}, (table) => [
    // Index for slug lookups (deterministic matching)
    index("idx_tasks_slug").on(table.slug),
    // Index for status filtering
    index("idx_tasks_status").on(table.status),
    // Index for user's tasks
    index("idx_tasks_user_id").on(table.userId),
    // Index for workspace's tasks
    index("idx_tasks_workspace_id").on(table.workspaceId),
    // Index for finding active tasks
    index("idx_tasks_active").on(table.status, table.workspaceId),
    // Index for lineage queries
    index("idx_tasks_continues_from").on(table.continuesFrom),
]);
// =============================================================================
// TASK EVENTS TABLE
// =============================================================================
/**
 * Task events table - ordered log of all MCP tool calls and outcomes
 *
 * Events are append-only. The seq field provides ordering within a task.
 */
export const taskEvents = pgTable("task_events", {
    // Primary key
    id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
    // Task reference
    taskId: integer("task_id")
        .notNull()
        .references(() => tasks.id, { onDelete: "cascade" }),
    // Sequence number within task (monotonically increasing)
    seq: integer("seq").notNull(),
    // Event type
    type: taskEventTypeEnum("type").notNull(),
    // JSON-serialized event payload
    payloadJson: text("payload_json"),
    // Timestamp
    timestamp: timestamp("timestamp").notNull().defaultNow(),
}, (table) => [
    // Unique constraint on task_id + seq for ordering
    uniqueIndex("idx_task_events_task_seq").on(table.taskId, table.seq),
    // Index for task lookup
    index("idx_task_events_task_id").on(table.taskId),
    // Index for event type filtering
    index("idx_task_events_type").on(table.type),
]);
// =============================================================================
// TASK FILES TABLE
// =============================================================================
/**
 * Task files table - file change log entries
 *
 * Files are tracked by the daemon autonomously via Git diff.
 * All writes are append-only.
 */
export const taskFiles = pgTable("task_files", {
    // Primary key
    id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
    // Task reference
    taskId: integer("task_id")
        .notNull()
        .references(() => tasks.id, { onDelete: "cascade" }),
    // Relative POSIX path from workspace root
    path: text("path").notNull(),
    // Type of file operation
    action: fileActionEnum("action").notNull(),
    // SHA-256 hash before change (null for added files)
    hashBefore: text("hash_before"),
    // SHA-256 hash after change (null for deleted files)
    hashAfter: text("hash_after"),
    // Timestamp
    timestamp: timestamp("timestamp").notNull().defaultNow(),
}, (table) => [
    // Index for task lookup
    index("idx_task_files_task_id").on(table.taskId),
    // Index for path lookup within task
    index("idx_task_files_task_path").on(table.taskId, table.path),
]);
// =============================================================================
// TASK LEARNINGS TABLE
// =============================================================================
/**
 * Task learnings table - captured insights attached to tasks
 *
 * Learnings are deduplicated by content hash and dual-written to:
 * 1. Task-scoped (this table)
 * 2. Global knowledge store (vector_learnings table)
 */
export const taskLearnings = pgTable("task_learnings", {
    // Primary key
    id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
    // Task reference
    taskId: integer("task_id")
        .notNull()
        .references(() => tasks.id, { onDelete: "cascade" }),
    // SHA-256 hash of content for deduplication
    contentHash: text("content_hash").notNull(),
    // The actual learning content
    content: text("content").notNull(),
    // Category classification
    category: learningCategoryEnum("category"),
    // Where this learning came from
    source: text("source"),
    // Confidence level
    confidence: learningConfidenceEnum("confidence").default("medium"),
    // Timestamp
    timestamp: timestamp("timestamp").notNull().defaultNow(),
}, (table) => [
    // Unique constraint on task_id + content_hash for deduplication
    uniqueIndex("idx_task_learnings_task_hash").on(table.taskId, table.contentHash),
    // Index for task lookup
    index("idx_task_learnings_task_id").on(table.taskId),
    // Index for category filtering
    index("idx_task_learnings_category").on(table.category),
]);
// =============================================================================
// TASK SESSIONS TABLE
// =============================================================================
/**
 * Task sessions table - record of each daemon connection to a Task
 *
 * Sessions are transient connections that come and go underneath a Task.
 * When a session disconnects, the Task remains in its current state.
 */
export const taskSessions = pgTable("task_sessions", {
    // Primary key
    id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
    // Task reference
    taskId: integer("task_id")
        .notNull()
        .references(() => tasks.id, { onDelete: "cascade" }),
    // Unique session identifier (UUID)
    sessionId: text("session_id").notNull(),
    // Whether this session is the writer (can modify task state)
    isWriter: boolean("is_writer").notNull().default(true),
    // Timestamps
    connectedAt: timestamp("connected_at").notNull().defaultNow(),
    disconnectedAt: timestamp("disconnected_at"),
}, (table) => [
    // Index for task lookup
    index("idx_task_sessions_task_id").on(table.taskId),
    // Index for session lookup
    index("idx_task_sessions_session_id").on(table.sessionId),
    // Index for finding active sessions
    index("idx_task_sessions_active").on(table.taskId, table.disconnectedAt),
]);
// =============================================================================
// RELATIONS
// =============================================================================
/**
 * Task relations
 */
export const tasksRelations = relations(tasks, ({ one, many }) => ({
    // User who owns this task
    user: one(user, {
        fields: [tasks.userId],
        references: [user.id],
    }),
    // Task this continues from (lineage)
    continuedFrom: one(tasks, {
        fields: [tasks.continuesFrom],
        references: [tasks.id],
        relationName: "task_lineage",
    }),
    // Tasks that continue from this task
    continuedBy: many(tasks, {
        relationName: "task_lineage",
    }),
    // Events for this task
    events: many(taskEvents),
    // File changes for this task
    files: many(taskFiles),
    // Learnings for this task
    learnings: many(taskLearnings),
    // Sessions for this task
    sessions: many(taskSessions),
}));
/**
 * Task events relations
 */
export const taskEventsRelations = relations(taskEvents, ({ one }) => ({
    // Task this event belongs to
    task: one(tasks, {
        fields: [taskEvents.taskId],
        references: [tasks.id],
    }),
}));
/**
 * Task files relations
 */
export const taskFilesRelations = relations(taskFiles, ({ one }) => ({
    // Task this file belongs to
    task: one(tasks, {
        fields: [taskFiles.taskId],
        references: [tasks.id],
    }),
}));
/**
 * Task learnings relations
 */
export const taskLearningsRelations = relations(taskLearnings, ({ one }) => ({
    // Task this learning belongs to
    task: one(tasks, {
        fields: [taskLearnings.taskId],
        references: [tasks.id],
    }),
}));
/**
 * Task sessions relations
 */
export const taskSessionsRelations = relations(taskSessions, ({ one }) => ({
    // Task this session belongs to
    task: one(tasks, {
        fields: [taskSessions.taskId],
        references: [tasks.id],
    }),
}));
// =============================================================================
// DERIVED COUNTER FUNCTIONS
// =============================================================================
/**
 * Compute derived counters from accumulated state.
 *
 * CRITICAL: These are NEVER stored independently.
 * They are always computed from the accumulated state.
 * This eliminates the ceremony zeros bug by construction.
 */
/**
 * SQL to compute file change counts by action type
 * Used for ceremony metrics
 */
export const fileChangeCountsSql = sql `
	SELECT 
		COUNT(DISTINCT CASE WHEN action = 'modified' THEN path END) as files_modified,
		COUNT(DISTINCT CASE WHEN action = 'added' THEN path END) as files_created,
		COUNT(DISTINCT CASE WHEN action = 'deleted' THEN path END) as files_deleted,
		COUNT(*) as total_file_operations
	FROM task_files
	WHERE task_id = $taskId
`;
/**
 * SQL to count learnings for a task
 */
export const learningCountSql = sql `
	SELECT COUNT(*) as count
	FROM task_learnings
	WHERE task_id = $taskId
`;
/**
 * SQL to count sessions for a task
 */
export const sessionCountSql = sql `
	SELECT COUNT(*) as count
	FROM task_sessions
	WHERE task_id = $taskId
`;
/**
 * SQL to count pulses (pulse_recorded events) for a task
 */
export const pulseCountSql = sql `
	SELECT COUNT(*) as count
	FROM task_events
	WHERE task_id = $taskId AND type = 'pulse_recorded'
`;
