// ESM imports fixed for Node.js v22+
import { relations } from "drizzle-orm";
import { index, jsonb, pgTable, text, timestamp, uniqueIndex, uuid } from "drizzle-orm/pg-core";
import { member, organization } from "../postgres.js";
/**
 * Repositories - canonical workspace/repository dimension.
 *
 * Each repository belongs to a single organization (tenant) and represents
 * either a GitHub repo or a local workspace, identified by provider-specific
 * metadata. Other tables should reference repositories.id instead of using
 * free-form workspace or repo identifiers.
 */
export const repositories = pgTable("repositories", {
    id: uuid("id").primaryKey().defaultRandom(),
    organizationId: text("organization_id")
        .notNull()
        .references(() => organization.id, { onDelete: "cascade" }),
    provider: text("provider").notNull().default("github"),
    externalRepoId: text("external_repo_id"),
    fullName: text("full_name").notNull(),
    visibility: text("visibility").default("private"),
    metadata: jsonb("metadata").$type().default({}),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
}, (table) => ({
    orgNameIdx: index("repositories_org_full_name_idx").on(table.organizationId, table.fullName),
    externalIdx: index("repositories_external_idx").on(table.provider, table.externalRepoId),
}));
/**
 * Repo memberships - per-repository access control.
 *
 * Links an organization membership (member) to a repository with a role and
 * optional permissions. This is the canonical place for repo-scoped roles.
 */
export const repoMemberships = pgTable("repo_memberships", {
    id: uuid("id").primaryKey().defaultRandom(),
    membershipId: text("membership_id")
        .notNull()
        .references(() => member.id, { onDelete: "cascade" }),
    repositoryId: uuid("repository_id")
        .notNull()
        .references(() => repositories.id, { onDelete: "cascade" }),
    role: text("role").notNull().default("contributor"),
    permissions: jsonb("permissions").$type().default({}),
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
}, (table) => ({
    membershipRepoUnique: uniqueIndex("repo_memberships_membership_repo_unique").on(table.membershipId, table.repositoryId),
    repoIdx: index("repo_memberships_repo_idx").on(table.repositoryId),
}));
export const repositoriesRelations = relations(repositories, ({ one }) => ({
    organization: one(organization, {
        fields: [repositories.organizationId],
        references: [organization.id],
    }),
}));
export const repoMembershipsRelations = relations(repoMemberships, ({ one }) => ({
    membership: one(member, {
        fields: [repoMemberships.membershipId],
        references: [member.id],
    }),
    repository: one(repositories, {
        fields: [repoMemberships.repositoryId],
        references: [repositories.id],
    }),
}));
