// ESM imports fixed for Node.js v22+
import { relations } from "drizzle-orm";
import { boolean, integer, json, pgEnum, pgTable, text, timestamp } from "drizzle-orm/pg-core";
import { nanoid } from "nanoid";
import { organization, usageLimits, user } from "../postgres.js";
// Enums - matching those in postgres.ts
export const planTypeEnum = pgEnum("plan_type", ["free", "pro", "team", "enterprise"]);
/**
 * Subscription status enum with full lifecycle states.
 *
 * State transitions:
 * - free → trialing (trial started)
 * - trialing → active (trial converted)
 * - trialing → canceled (trial ended without payment)
 * - active → past_due (payment failed)
 * - past_due → active (payment succeeded)
 * - past_due → suspended (grace period expired)
 * - suspended → active (payment method updated)
 * - suspended → churned (period ends without reactivation)
 * - active → canceled (user canceled, end of term)
 * - canceled → churned (subscription period ended)
 *
 * @see implementation-plan.md Part 2.1 Account State Machine
 */
export const subscriptionStatusEnum = pgEnum("subscription_status", [
    "active",
    "canceled",
    "past_due",
    "trialing",
    "paused",
    "suspended", // Grace period expired, cloud features paused
    "churned", // Subscription fully ended, no renewal
]);
// Subscriptions table - matching the definition in postgres.ts
export const subscriptions = pgTable("subscriptions", {
    id: text("id")
        .primaryKey()
        .$defaultFn(() => nanoid()),
    userId: text("user_id").references(() => user.id, {
        onDelete: "cascade",
    }),
    organizationId: text("organization_id").references(() => organization.id, {
        onDelete: "cascade",
    }),
    stripeSubscriptionId: text("stripe_subscription_id").unique(),
    stripeCustomerId: text("stripe_customer_id"),
    plan: planTypeEnum("plan").notNull().default("free"),
    status: subscriptionStatusEnum("status").notNull().default("active"),
    currentPeriodStart: timestamp("current_period_start"),
    currentPeriodEnd: timestamp("current_period_end"),
    cancelAtPeriodEnd: boolean("cancel_at_period_end").default(false),
    trialEnd: timestamp("trial_end"),
    seats: integer("seats").default(1),
    metadata: json("metadata"),
    // Credit system fields (pricing_spec_v3.md)
    monthlyCreditsAllowance: integer("monthly_credits_allowance").default(25), // 25 for free, 200 for pro/team
    currentCreditBalance: integer("current_credit_balance").default(0), // Included credits remaining this period
    topupCreditBalance: integer("topup_credit_balance").default(0), // Purchased credits (never expire)
    creditOverage: integer("credit_overage").default(0), // Negative balance tracking (soft cap at -100)
    createdAt: timestamp("created_at").defaultNow().notNull(),
    updatedAt: timestamp("updated_at").defaultNow().notNull(),
});
export const subscriptionsRelations = relations(subscriptions, ({ one, many }) => ({
    user: one(user, {
        fields: [subscriptions.userId],
        references: [user.id],
    }),
    organization: one(organization, {
        fields: [subscriptions.organizationId],
        references: [organization.id],
    }),
    limits: many(usageLimits),
}));
