// ESM imports fixed for Node.js v22+
/**
 * Super Admin Schema
 *
 * Tables for Super Admin panel functionality:
 * - Activation codes for trials and enterprise onboarding
 * - Admin audit logging for compliance
 * - Super admin role management
 */
import { relations, sql } from "drizzle-orm";
import { index, integer, jsonb, pgEnum, pgTable, text, timestamp, unique, uuid, varchar } from "drizzle-orm/pg-core";
import { user } from "../postgres.js";
import { subscriptions } from "./subscriptions.js";
// =============================================================================
// Enums
// =============================================================================
/**
 * Activation code types
 */
export const activationCodeTypeEnum = pgEnum("activation_code_type", [
    "TRIAL",
    "ENTERPRISE",
    "PIONEER",
    "LIFETIME",
    "PROMOTIONAL",
]);
/**
 * Admin action types for audit logging
 */
export const adminActionEnum = pgEnum("admin_action", [
    "CODE_CREATED",
    "CODE_REVOKED",
    "CODE_BATCH_CREATED",
    "SUBSCRIPTION_OVERRIDE",
    "USER_IMPERSONATED",
    "ORG_CREATED",
    "TIER_CHANGED",
    "USER_SUSPENDED",
    "USER_UNSUSPENDED",
    "TRIAL_EXTENDED",
    "ADMIN_ADDED",
    "ADMIN_REMOVED",
]);
/**
 * Admin target types for audit logging
 */
export const adminTargetTypeEnum = pgEnum("admin_target_type", [
    "USER",
    "ORGANIZATION",
    "SUBSCRIPTION",
    "CODE",
    "ADMIN",
]);
/**
 * Super admin role levels
 */
export const superAdminRoleEnum = pgEnum("super_admin_role", ["OWNER", "ADMIN", "SUPPORT", "READONLY"]);
// =============================================================================
// Tables
// =============================================================================
/**
 * Activation Codes - for trials and enterprise onboarding
 *
 * Code format: SB-{TYPE}-{RANDOM}
 * Examples: SB-TRIAL-A7X9K2, SB-ENT-M3P8Q1, SB-VIP-Z5N2R4
 */
export const activationCodes = pgTable("activation_codes", {
    id: uuid("id").primaryKey().defaultRandom(),
    // Code identifier (SB-TYPE-RANDOM format)
    code: varchar("code", { length: 32 }).unique().notNull(),
    // Code configuration
    type: activationCodeTypeEnum("type").notNull(),
    tier: varchar("tier", { length: 50 }), // 'pro', 'enterprise', etc.
    durationDays: integer("duration_days"), // null = unlimited
    maxRedemptions: integer("max_redemptions").default(1).notNull(),
    currentRedemptions: integer("current_redemptions").default(0).notNull(),
    // Campaign tracking
    campaign: varchar("campaign", { length: 100 }), // 'yc_demo', 'producthunt'
    notes: text("notes"),
    // Validity period
    expiresAt: timestamp("expires_at", { withTimezone: true }),
    validFrom: timestamp("valid_from", { withTimezone: true }).defaultNow().notNull(),
    // Creation metadata
    createdById: text("created_by_id")
        .notNull()
        .references(() => user.id, { onDelete: "set null" }),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    // Revocation (soft delete)
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
    revokedById: text("revoked_by_id").references(() => user.id, { onDelete: "set null" }),
    revokedReason: text("revoked_reason"),
}, (table) => [
    // Unique constraint on code
    index("activation_codes_code_idx").on(table.code),
    // Query by creator
    index("activation_codes_created_by_idx").on(table.createdById, table.createdAt),
    // Active codes by type (for dashboard stats)
    index("activation_codes_active_type_idx")
        .on(table.type)
        .where(sql `revoked_at IS NULL`),
    // Campaign tracking
    index("activation_codes_campaign_idx").on(table.campaign),
]);
/**
 * Activation Code Redemptions - audit trail for code usage
 */
export const activationCodeRedemptions = pgTable("activation_code_redemptions", {
    id: uuid("id").primaryKey().defaultRandom(),
    // Code reference
    codeId: uuid("code_id")
        .notNull()
        .references(() => activationCodes.id, { onDelete: "cascade" }),
    // User who redeemed
    userId: text("user_id")
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    // What was granted
    tierGranted: varchar("tier_granted", { length: 50 }).notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }), // null = permanent
    // Redemption metadata
    redeemedAt: timestamp("redeemed_at", { withTimezone: true }).defaultNow().notNull(),
    ipAddress: varchar("ip_address", { length: 45 }),
    userAgent: text("user_agent"),
    // Linked subscription (if created)
    subscriptionId: text("subscription_id").references(() => subscriptions.id, {
        onDelete: "set null",
    }),
}, (table) => [
    // Prevent double redemption by same user
    unique("activation_code_redemptions_unique").on(table.codeId, table.userId),
    // Query redemptions by user
    index("activation_code_redemptions_user_idx").on(table.userId, table.redeemedAt),
    // Query redemptions by code
    index("activation_code_redemptions_code_idx").on(table.codeId),
]);
/**
 * Admin Audit Log - track all super admin actions
 */
export const adminAuditLog = pgTable("admin_audit_log", {
    id: uuid("id").primaryKey().defaultRandom(),
    // Who performed the action
    adminId: text("admin_id")
        .notNull()
        .references(() => user.id, { onDelete: "set null" }),
    // What action was performed
    action: adminActionEnum("action").notNull(),
    // Target of the action
    targetType: adminTargetTypeEnum("target_type").notNull(),
    targetId: text("target_id"), // UUID or text ID depending on target type
    // Action-specific details
    metadata: jsonb("metadata").$type(),
    // Request context
    ipAddress: varchar("ip_address", { length: 45 }),
    userAgent: text("user_agent"),
    // Timestamp
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
}, (table) => [
    // Query by admin
    index("admin_audit_log_admin_idx").on(table.adminId, table.createdAt),
    // Query by target
    index("admin_audit_log_target_idx").on(table.targetType, table.targetId),
    // Query by action type
    index("admin_audit_log_action_idx").on(table.action, table.createdAt),
    // Time-based queries
    index("admin_audit_log_created_at_idx").on(table.createdAt),
]);
/**
 * Super Admins - who can access the admin panel
 */
export const superAdmins = pgTable("super_admins", {
    id: uuid("id").primaryKey().defaultRandom(),
    // User reference (one-to-one)
    userId: text("user_id")
        .unique()
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    // Role level
    role: superAdminRoleEnum("role").notNull().default("READONLY"),
    // Granular permissions (JSON object)
    // e.g., { "codes.create": true, "users.suspend": false }
    permissions: jsonb("permissions").$type(),
    // Who added this admin
    addedById: text("added_by_id").references(() => user.id, { onDelete: "set null" }),
    // Timestamps
    addedAt: timestamp("added_at", { withTimezone: true }).defaultNow().notNull(),
    lastAccessAt: timestamp("last_access_at", { withTimezone: true }),
}, (table) => [
    // Fast lookup by user
    index("super_admins_user_idx").on(table.userId),
    // Query by role
    index("super_admins_role_idx").on(table.role),
]);
// =============================================================================
// Relations
// =============================================================================
export const activationCodesRelations = relations(activationCodes, ({ one, many }) => ({
    createdBy: one(user, {
        fields: [activationCodes.createdById],
        references: [user.id],
        relationName: "codeCreator",
    }),
    revokedBy: one(user, {
        fields: [activationCodes.revokedById],
        references: [user.id],
        relationName: "codeRevoker",
    }),
    redemptions: many(activationCodeRedemptions),
}));
export const activationCodeRedemptionsRelations = relations(activationCodeRedemptions, ({ one }) => ({
    code: one(activationCodes, {
        fields: [activationCodeRedemptions.codeId],
        references: [activationCodes.id],
    }),
    user: one(user, {
        fields: [activationCodeRedemptions.userId],
        references: [user.id],
    }),
    subscription: one(subscriptions, {
        fields: [activationCodeRedemptions.subscriptionId],
        references: [subscriptions.id],
    }),
}));
export const adminAuditLogRelations = relations(adminAuditLog, ({ one }) => ({
    admin: one(user, {
        fields: [adminAuditLog.adminId],
        references: [user.id],
    }),
}));
export const superAdminsRelations = relations(superAdmins, ({ one }) => ({
    user: one(user, {
        fields: [superAdmins.userId],
        references: [user.id],
    }),
    addedBy: one(user, {
        fields: [superAdmins.addedById],
        references: [user.id],
        relationName: "adminAdder",
    }),
}));
// =============================================================================
// Admin Email Sends (0024_admin_dashboard_tables)
// =============================================================================
/**
 * Admin Email Sends - audit trail for admin-initiated emails
 */
export const adminEmailSends = pgTable("admin_email_sends", {
    id: uuid("id").primaryKey().defaultRandom(),
    adminUserId: text("admin_user_id")
        .notNull()
        .references(() => user.id, { onDelete: "set null" }),
    recipientEmail: text("recipient_email").notNull(),
    recipientUserId: text("recipient_user_id").references(() => user.id, { onDelete: "set null" }),
    template: text("template").notNull(),
    subject: text("subject").notNull(),
    bodyPreview: text("body_preview"),
    resendId: text("resend_id"),
    sentAt: timestamp("sent_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => [
    index("admin_email_sends_admin_idx").on(table.adminUserId, table.sentAt),
    index("admin_email_sends_recipient_idx").on(table.recipientUserId),
]);
// =============================================================================
// Admin Tier Changes (0024_admin_dashboard_tables)
// =============================================================================
/**
 * Admin Tier Changes - audit trail for admin tier overrides
 * These are manual overrides only  -  separate from Stripe billing.
 */
export const adminTierChanges = pgTable("admin_tier_changes", {
    id: uuid("id").primaryKey().defaultRandom(),
    adminUserId: text("admin_user_id")
        .notNull()
        .references(() => user.id, { onDelete: "set null" }),
    targetUserId: text("target_user_id")
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    previousTier: text("previous_tier").notNull(),
    newTier: text("new_tier").notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }),
    reason: text("reason").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
}, (table) => [index("admin_tier_changes_target_idx").on(table.targetUserId, table.createdAt)]);
