// ESM imports fixed for Node.js v22+
/**
 * Conflict Log - Abuse Defense Phase 1
 *
 * Logs device and codebase conflicts for abuse monitoring.
 * Phase 1: Log conflicts, notify users, but never hard-block.
 */
import { relations } from "drizzle-orm";
import { index, integer, jsonb, pgTable, timestamp, varchar } from "drizzle-orm/pg-core";
import { user } from "../postgres.js";
/**
 * Conflict Log table - Records device/codebase conflicts
 */
export const conflictLog = pgTable("conflict_log", {
    id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
    /** Type of conflict: "device" | "codebase" */
    type: varchar("type", { length: 20 }).notNull(),
    /** Device hash involved in conflict */
    machineIdHash: varchar("machine_id_hash", { length: 64 }),
    /** Codebase hash involved in conflict */
    codebaseHash: varchar("codebase_hash", { length: 64 }),
    /** Account that previously owned the device/codebase */
    existingAccountId: varchar("existing_account_id", { length: 255 })
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    /** Account attempting to bind */
    newAccountId: varchar("new_account_id", { length: 255 })
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    /** Enrichment: IP, user agent, etc. added async */
    metadata: jsonb("metadata").$type(),
    /** When the conflict was detected */
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    /** null = unresolved, "legitimate" | "abuse" | "dismissed" */
    resolution: varchar("resolution", { length: 20 }),
    resolvedAt: timestamp("resolved_at", { withTimezone: true }),
}, (table) => [
    /** Index for type-based queries */
    index("conflict_log_type_idx").on(table.type),
    /** Index for existing account lookups */
    index("conflict_log_existing_account_idx").on(table.existingAccountId),
    /** Index for new account lookups */
    index("conflict_log_new_account_idx").on(table.newAccountId),
    /** Index for time-based queries */
    index("conflict_log_created_at_idx").on(table.createdAt),
]);
// Relations
export const conflictLogRelations = relations(conflictLog, ({ one }) => ({
    existingAccount: one(user, {
        fields: [conflictLog.existingAccountId],
        references: [user.id],
    }),
    newAccount: one(user, {
        fields: [conflictLog.newAccountId],
        references: [user.id],
    }),
}));
