// ESM imports fixed for Node.js v22+
/**
 * Enterprise Auth Schema
 *
 * Tables for enterprise authentication features:
 * - SSO configuration (providers)
 * - SSO sessions
 * - SSO attribute mappings
 * - Risk-based authentication
 * - Trusted device management
 * - Session context tracking
 * - Conditional access policies
 * - Enterprise audit logging
 */
import { relations, sql } from "drizzle-orm";
import { boolean, index, integer, jsonb, pgEnum, pgTable, text, timestamp, unique, uuid, varchar, } from "drizzle-orm/pg-core";
import { organization, user } from "../postgres.js";
// =============================================================================
// SSO Provider Enums
// =============================================================================
/**
 * Supported SSO providers
 */
export const ssoProviderEnum = pgEnum("sso_provider", [
    "okta",
    "azure_ad",
    "google_workspace",
    "onelogin",
    "ping_identity",
    "custom_saml",
    "custom_oidc",
]);
/**
 * SSO protocol types
 */
export const ssoProtocolEnum = pgEnum("sso_protocol", ["saml2", "oidc"]);
/**
 * SSO provider status
 */
export const ssoProviderStatusEnum = pgEnum("sso_provider_status", ["active", "inactive", "testing"]);
// =============================================================================
// SSO Configuration Table (Drizzle version of SQL migration 0016)
// =============================================================================
/**
 * SSO Configuration - enterprise IdP configuration per organization
 *
 * Stores SAML/OIDC configuration for enterprise single sign-on
 */
export const ssoConfiguration = pgTable("sso_configuration", {
    configId: uuid("config_id").primaryKey().defaultRandom(),
    // Organization reference
    organizationId: text("organization_id")
        .notNull()
        .references(() => organization.id, { onDelete: "cascade" }),
    // Provider info
    provider: ssoProviderEnum("provider").notNull(),
    protocol: ssoProtocolEnum("protocol").notNull(),
    // Status flags
    isEnabled: boolean("is_enabled").default(false).notNull(),
    enforceSso: boolean("enforce_sso").default(false).notNull(),
    // SAML configuration
    samlConfig: jsonb("saml_config").$type(),
    // OIDC configuration
    oidcConfig: jsonb("oidc_config").$type(),
    // Domain restrictions
    allowedDomains: text("allowed_domains").array(),
    // Auto-provisioning settings
    autoProvisioning: jsonb("auto_provisioning")
        .$type()
        .default({ enabled: false, defaultRole: "member", syncGroups: false }),
    // Timestamps
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
    lastAuthAt: timestamp("last_auth_at", { withTimezone: true }),
}, (table) => [
    // Query by organization
    index("sso_config_org_idx").on(table.organizationId),
    // Query enabled configs
    index("sso_config_enabled_idx")
        .on(table.isEnabled)
        .where(sql `is_enabled = true`),
    // Unique config per org
    unique("sso_config_unique_org").on(table.organizationId),
]);
/**
 * SSO Session - tracks SSO-authenticated sessions for single logout
 */
export const ssoSession = pgTable("sso_session", {
    sessionId: uuid("session_id").primaryKey().defaultRandom(),
    // User reference
    userId: text("user_id")
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    // SSO config reference
    ssoConfigId: uuid("sso_config_id")
        .notNull()
        .references(() => ssoConfiguration.configId, { onDelete: "cascade" }),
    // IdP session info (for single logout)
    idpSessionId: text("idp_session_id"),
    // Session timing
    authenticatedAt: timestamp("authenticated_at", { withTimezone: true }).defaultNow().notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    // Client info
    ipAddress: varchar("ip_address", { length: 45 }),
    userAgent: text("user_agent"),
}, (table) => [
    // Query by user
    index("sso_session_user_idx").on(table.userId),
    // Query by config
    index("sso_session_config_idx").on(table.ssoConfigId),
    // Cleanup expired sessions
    index("sso_session_expires_idx").on(table.expiresAt),
    // Lookup by IdP session ID
    index("sso_session_idp_idx")
        .on(table.idpSessionId)
        .where(sql `idp_session_id IS NOT NULL`),
]);
// =============================================================================
// Enums
// =============================================================================
/**
 * Attribute transform types for SSO mapping
 */
export const transformTypeEnum = pgEnum("transform_type", ["DIRECT", "REGEX", "LOOKUP", "CUSTOM"]);
/**
 * Risk assessment decision outcomes
 */
export const riskDecisionEnum = pgEnum("risk_decision", ["ALLOW", "CHALLENGE_MFA", "CHALLENGE_EMAIL", "BLOCK"]);
/**
 * Authentication methods for session context
 */
export const authMethodEnum = pgEnum("auth_method", [
    "PASSWORD",
    "SSO_SAML",
    "SSO_OIDC",
    "API_KEY",
    "OAUTH",
    "MAGIC_LINK",
    "PASSKEY",
]);
/**
 * Actor types for enterprise audit log
 */
export const actorTypeEnum = pgEnum("actor_type", ["USER", "SYSTEM", "API"]);
// =============================================================================
// Tables
// =============================================================================
/**
 * SSO Attribute Mappings - map IdP attributes to Vreko fields
 *
 * Used during SSO login to transform IdP-provided attributes
 * into Vreko user fields (e.g., groups -> role)
 */
export const ssoAttributeMappings = pgTable("sso_attribute_mappings", {
    id: uuid("id").primaryKey().defaultRandom(),
    // Reference to SSO configuration (from 0016 migration)
    // Note: We use text since sso_configuration uses uuid but we reference by config_id
    configId: uuid("config_id").notNull(),
    // Mapping definition
    sourceAttribute: varchar("source_attribute", { length: 100 }).notNull(), // "groups", "department"
    targetField: varchar("target_field", { length: 100 }).notNull(), // "role", "team"
    // Transform configuration
    transformType: transformTypeEnum("transform_type").notNull().default("DIRECT"),
    transformConfig: jsonb("transform_config").$type(),
    // Validation
    isRequired: boolean("is_required").default(false).notNull(),
    defaultValue: text("default_value"),
    // Timestamps
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
}, (table) => [
    // Query mappings by config
    index("sso_attribute_mappings_config_idx").on(table.configId),
    // Unique mapping per source/target pair per config
    unique("sso_attribute_mappings_unique").on(table.configId, table.sourceAttribute, table.targetField),
]);
/**
 * Risk Assessments - login risk scoring
 *
 * Calculated during authentication to determine if additional
 * verification is required (MFA, email challenge, or block)
 */
export const riskAssessments = pgTable("risk_assessments", {
    id: uuid("id").primaryKey().defaultRandom(),
    // User context
    userId: text("user_id")
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    sessionId: varchar("session_id", { length: 100 }),
    // Risk calculation
    score: integer("score").notNull(), // 0-100
    factors: jsonb("factors").notNull().$type(),
    decision: riskDecisionEnum("decision").notNull(),
    // Challenge tracking
    challengeCompleted: boolean("challenge_completed"),
    // Request context
    ipAddress: varchar("ip_address", { length: 45 }),
    userAgent: text("user_agent"),
    geoLocation: jsonb("geo_location").$type(),
    // Timestamp
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
}, (table) => [
    // Query by user
    index("risk_assessments_user_idx").on(table.userId, table.createdAt),
    // Query by decision for analytics
    index("risk_assessments_decision_idx").on(table.decision, table.createdAt),
    // Query by score range for analytics
    index("risk_assessments_score_idx").on(table.score),
]);
/**
 * Trusted Devices - skip MFA for known devices
 *
 * When a user marks a device as trusted after MFA,
 * future logins from that device skip the MFA challenge
 */
export const trustedDevices = pgTable("trusted_devices", {
    id: uuid("id").primaryKey().defaultRandom(),
    // User owner
    userId: text("user_id")
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    // Device identification
    deviceFingerprint: varchar("device_fingerprint", { length: 64 }).notNull(),
    deviceName: varchar("device_name", { length: 100 }), // "Chrome on MacBook Pro"
    // Usage tracking
    lastUsedAt: timestamp("last_used_at", { withTimezone: true }).defaultNow().notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(), // Trust expires after 30 days
    // Origin context
    ipAddress: varchar("ip_address", { length: 45 }),
}, (table) => [
    // Unique device per user
    unique("trusted_devices_unique").on(table.userId, table.deviceFingerprint),
    // Query by user
    index("trusted_devices_user_idx").on(table.userId),
    // Cleanup expired devices
    index("trusted_devices_expires_idx").on(table.expiresAt),
]);
/**
 * User Session Context - rich session data for audit
 *
 * Captures detailed context about each session for
 * security monitoring and compliance requirements
 */
export const userSessionContext = pgTable("user_session_context", {
    id: uuid("id").primaryKey().defaultRandom(),
    // Session identity
    sessionId: varchar("session_id", { length: 100 }).unique().notNull(),
    // User reference
    userId: text("user_id")
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    // Authentication details
    authMethod: authMethodEnum("auth_method").notNull(),
    ssoConfigId: uuid("sso_config_id"), // Reference to sso_configuration
    riskAssessmentId: uuid("risk_assessment_id").references(() => riskAssessments.id, {
        onDelete: "set null",
    }),
    // MFA status
    mfaCompleted: boolean("mfa_completed").default(false).notNull(),
    mfaMethod: varchar("mfa_method", { length: 50 }), // "totp", "backup_code", "passkey"
    // Request context
    ipAddress: varchar("ip_address", { length: 45 }),
    userAgent: text("user_agent"),
    geoLocation: jsonb("geo_location").$type(),
    // Lifecycle timestamps
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    lastActivityAt: timestamp("last_activity_at", { withTimezone: true }).defaultNow().notNull(),
    terminatedAt: timestamp("terminated_at", { withTimezone: true }),
    terminationReason: varchar("termination_reason", { length: 100 }), // "logout", "expired", "revoked", "suspicious"
}, (table) => [
    // Query by user
    index("user_session_context_user_idx").on(table.userId, table.createdAt),
    // Active sessions
    index("user_session_context_active_idx")
        .on(table.userId)
        .where(sql `terminated_at IS NULL`),
    // Query by auth method for analytics
    index("user_session_context_method_idx").on(table.authMethod),
]);
/**
 * Conditional Access Policies - enterprise auth rules
 *
 * Organization-specific policies that control authentication
 * requirements based on conditions (IP range, time, device, etc.)
 */
export const conditionalAccessPolicies = pgTable("conditional_access_policies", {
    id: uuid("id").primaryKey().defaultRandom(),
    // Organization scope
    organizationId: text("organization_id")
        .notNull()
        .references(() => organization.id, { onDelete: "cascade" }),
    // Policy definition
    name: varchar("name", { length: 100 }).notNull(),
    description: text("description"),
    priority: integer("priority").default(0).notNull(), // Lower = higher priority
    isEnabled: boolean("is_enabled").default(true).notNull(),
    // Conditions - when this policy applies
    conditions: jsonb("conditions").notNull().$type(),
    // Actions - what to do when conditions match
    actions: jsonb("actions").notNull().$type(),
    // Metadata
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).defaultNow().notNull(),
    createdById: text("created_by_id").references(() => user.id, { onDelete: "set null" }),
}, (table) => [
    // Query policies by org
    index("conditional_access_policies_org_idx").on(table.organizationId),
    // Active policies by priority
    index("conditional_access_policies_active_idx")
        .on(table.organizationId, table.priority)
        .where(sql `is_enabled = true`),
]);
/**
 * Enterprise Audit Log - per-org audit trail
 *
 * Detailed audit log for enterprise compliance,
 * partitioned by time for efficient retention management
 */
export const enterpriseAuditLog = pgTable("enterprise_audit_log", {
    id: uuid("id").primaryKey().defaultRandom(),
    // Organization scope
    organizationId: text("organization_id")
        .notNull()
        .references(() => organization.id, { onDelete: "cascade" }),
    // Actor (who performed the action)
    actorId: text("actor_id").references(() => user.id, { onDelete: "set null" }),
    actorType: actorTypeEnum("actor_type").notNull(),
    // Action details
    action: varchar("action", { length: 100 }).notNull(), // "sso.login", "member.invited", etc.
    resourceType: varchar("resource_type", { length: 100 }), // "user", "sso_config", "policy"
    resourceId: text("resource_id"),
    // Additional context
    metadata: jsonb("metadata").$type(),
    // Request context
    ipAddress: varchar("ip_address", { length: 45 }),
    userAgent: text("user_agent"),
    // Timestamp
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
}, (table) => [
    // Query by org and time (primary query pattern)
    index("enterprise_audit_log_org_time_idx").on(table.organizationId, table.createdAt),
    // Query by actor
    index("enterprise_audit_log_actor_idx").on(table.actorId),
    // Query by action type
    index("enterprise_audit_log_action_idx").on(table.action, table.createdAt),
    // Query by resource
    index("enterprise_audit_log_resource_idx").on(table.resourceType, table.resourceId),
]);
// =============================================================================
// Relations
// =============================================================================
export const ssoConfigurationRelations = relations(ssoConfiguration, ({ one, many }) => ({
    organization: one(organization, {
        fields: [ssoConfiguration.organizationId],
        references: [organization.id],
    }),
    attributeMappings: many(ssoAttributeMappings),
    sessions: many(ssoSession),
}));
export const ssoSessionRelations = relations(ssoSession, ({ one }) => ({
    user: one(user, {
        fields: [ssoSession.userId],
        references: [user.id],
    }),
    config: one(ssoConfiguration, {
        fields: [ssoSession.ssoConfigId],
        references: [ssoConfiguration.configId],
    }),
}));
export const ssoAttributeMappingsRelations = relations(ssoAttributeMappings, ({ one }) => ({
    config: one(ssoConfiguration, {
        fields: [ssoAttributeMappings.configId],
        references: [ssoConfiguration.configId],
    }),
}));
export const riskAssessmentsRelations = relations(riskAssessments, ({ one }) => ({
    user: one(user, {
        fields: [riskAssessments.userId],
        references: [user.id],
    }),
}));
export const trustedDevicesRelations = relations(trustedDevices, ({ one }) => ({
    user: one(user, {
        fields: [trustedDevices.userId],
        references: [user.id],
    }),
}));
export const userSessionContextRelations = relations(userSessionContext, ({ one }) => ({
    user: one(user, {
        fields: [userSessionContext.userId],
        references: [user.id],
    }),
    riskAssessment: one(riskAssessments, {
        fields: [userSessionContext.riskAssessmentId],
        references: [riskAssessments.id],
    }),
}));
export const conditionalAccessPoliciesRelations = relations(conditionalAccessPolicies, ({ one }) => ({
    organization: one(organization, {
        fields: [conditionalAccessPolicies.organizationId],
        references: [organization.id],
    }),
    createdBy: one(user, {
        fields: [conditionalAccessPolicies.createdById],
        references: [user.id],
    }),
}));
export const enterpriseAuditLogRelations = relations(enterpriseAuditLog, ({ one }) => ({
    organization: one(organization, {
        fields: [enterpriseAuditLog.organizationId],
        references: [organization.id],
    }),
    actor: one(user, {
        fields: [enterpriseAuditLog.actorId],
        references: [user.id],
    }),
}));
