// ESM imports fixed for Node.js v22+
/**
 * CI Outcomes  -  Pipeline results linked to AI-attributed changes.
 *
 * Each row represents one CI pipeline run that observed an ai_changes record.
 * Parent table: ai_changes (FK on ai_change_id with CASCADE delete)
 */
import { index, integer, pgTable, real, text, timestamp, uuid } from "drizzle-orm/pg-core";
import { aiChanges } from "./ai-changes.js";
// ============================================================================
// ci_outcomes Table
// ============================================================================
export const ciOutcomes = pgTable("ci_outcomes", {
    // Primary key  -  server-generated UUID
    id: uuid("id").primaryKey().defaultRandom(),
    // FK to ai_changes.id (UUID PK)  -  CASCADE on parent delete
    aiChangeId: uuid("ai_change_id")
        .notNull()
        .references(() => aiChanges.id, { onDelete: "cascade" }),
    // CI pipeline metadata
    pipeline: text("pipeline").$type().notNull(), // "github-actions" | "gitlab-ci" | "jenkins" | "other"
    status: text("status").$type().notNull(), // "passed" | "failed" | "skipped" | "pending"
    // Test counts
    testsPassed: integer("tests_passed"),
    testsFailed: integer("tests_failed"),
    // Coverage change (can be negative, e.g. -2.3 = lost 2.3% coverage)
    coverageDelta: real("coverage_delta"),
    // Pipeline duration
    durationMs: integer("duration_ms"),
    // Link to the CI run for drilldown
    runUrl: text("run_url"),
    // Timestamps
    occurredAt: timestamp("occurred_at", { withTimezone: true }).notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
}, (table) => ({
    aiChangeIdIdx: index("ci_outcomes_ai_change_id_idx").on(table.aiChangeId),
    statusIdx: index("ci_outcomes_status_idx").on(table.status),
    occurredAtIdx: index("ci_outcomes_occurred_at_idx").on(table.occurredAt),
}));
