import { and, eq, sql } from "drizzle-orm";
import { integer, pgTable, text, timestamp } from "drizzle-orm/pg-core";
import { nanoid } from "nanoid";
// ============================================================================
// Alpha Invite Codes
// ============================================================================
// Single-use or multi-use codes gating console.vreko.dev registration.
// Each code carries an optional label for cohort tracking.
// Replaces the Pioneer invite-code system with a minimal, auditable model.
// ============================================================================
export const inviteCodes = pgTable("invite_codes", {
    id: text("id")
        .primaryKey()
        .$defaultFn(() => nanoid()),
    code: text("code").notNull().unique(),
    // Creator (null = system-generated)
    createdBy: text("created_by"),
    // How many times this code can be redeemed
    maxUses: integer("max_uses").notNull().default(1),
    // Running count  -  incremented atomically on each redemption
    currentUses: integer("current_uses").notNull().default(0),
    // Optional human-readable cohort label (e.g. "beta-march-2026")
    label: text("label"),
    // Numeric cohort identifier for the accept flow (default cohort 1)
    cohort: integer("cohort").notNull().default(1),
    // Optional hard expiry
    expiresAt: timestamp("expires_at", { withTimezone: true }),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
    // Soft-delete: set to revoke a code without losing audit history
    revokedAt: timestamp("revoked_at", { withTimezone: true }),
    // Optional pre-authorized email  -  pioneer email-first access flow
    invitedEmail: text("invited_email"),
});
// ============================================================================
// Pending API Keys
// ============================================================================
// Short-lived (5-min TTL) table that bridges the gap between API key creation
// in the server-side user.create.after hook and the client reading it on the
// /activate/welcome page.  Only one pending key per userId at a time.
// ============================================================================
export const pendingApiKeys = pgTable("pending_api_keys", {
    userId: text("user_id").primaryKey(),
    rawKey: text("raw_key").notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
    // Discriminator for multi-purpose use (e.g. 'api_key' | 'pioneer_magic_claim')
    purpose: text("purpose").notNull().default("api_key"),
});
// ============================================================================
// Helper: atomic invite-code burn
// ============================================================================
// Returns the updated row if the burn succeeded, or null if the code was
// already exhausted (concurrent redemption caught here).
// ============================================================================
export async function burnInviteCode(
// biome-ignore lint/suspicious/noExplicitAny: accepts any Drizzle NodePgDatabase variant
db, codeId) {
    const rows = await db
        .update(inviteCodes)
        .set({
        currentUses: sql `${inviteCodes.currentUses} + 1`,
        updatedAt: new Date(),
    })
        .where(and(eq(inviteCodes.id, codeId), sql `${inviteCodes.currentUses} < ${inviteCodes.maxUses}`))
        .returning();
    return rows[0] ?? null;
}
