// ESM imports fixed for Node.js v22+
/**
 * Device Bindings - Abuse Defense Phase 1
 *
 * Tracks device-to-account bindings for abuse prevention.
 * One device can only be bound to one account (enforced by unique index).
 *
 * PRIVACY: Only hashed device fingerprints are stored.
 * Raw hardware identifiers NEVER leave the daemon.
 */
import { relations } from "drizzle-orm";
import { boolean, index, integer, pgTable, timestamp, uniqueIndex, varchar } from "drizzle-orm/pg-core";
import { user } from "../postgres.js";
/**
 * Device Bindings table - Maps device fingerprints to accounts
 */
export const deviceBindings = pgTable("device_bindings", {
    id: integer("id").primaryKey().generatedAlwaysAsIdentity(),
    /** SHA-256 hash (32 hex chars) from daemon device fingerprint */
    machineIdHash: varchar("machine_id_hash", { length: 64 }).notNull(),
    /** Account this device is bound to */
    accountId: varchar("account_id", { length: 255 })
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    /** VS Code machineId (Phase 2  -  nullable for now) */
    vscodeMachineId: varchar("vscode_machine_id", { length: 64 }),
    /** Platform signature (coarser, for fleet analytics) */
    platformSignature: varchar("platform_signature", { length: 64 }),
    /** Whether platform serial was available during fingerprinting */
    serialAvailable: boolean("serial_available").default(true),
    /** Server-side ground truth  -  survives ~/.vreko/ deletion */
    firstSeen: timestamp("first_seen", { withTimezone: true }).defaultNow().notNull(),
    /** Updated on every bind call */
    lastSeen: timestamp("last_seen", { withTimezone: true }).defaultNow().notNull(),
    /** Abuse trust score: starts at 100, degrades on suspicious signals */
    trustScore: integer("trust_score").default(100).notNull(),
}, (table) => [
    /** One device can only be bound to one account */
    uniqueIndex("uq_device_account").on(table.machineIdHash, table.accountId),
    /** Index for account lookups */
    index("device_bindings_account_id_idx").on(table.accountId),
    /** Index for device hash lookups */
    index("device_bindings_machine_id_idx").on(table.machineIdHash),
]);
// Relations
export const deviceBindingsRelations = relations(deviceBindings, ({ one }) => ({
    account: one(user, {
        fields: [deviceBindings.accountId],
        references: [user.id],
    }),
}));
