// ESM imports fixed for Node.js v22+
import { relations } from "drizzle-orm";
import { jsonb, pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";
import { user } from "../postgres.js";
// =============================================================================
// SCHEMA DEFINITION
// =============================================================================
/**
 * Capability Audit - Immutable change history for user detection capabilities
 *
 * Privacy: Pattern keys and metadata only, no code content (C-006)
 *
 * This table provides:
 * - Complete audit trail of all capability changes
 * - Before/after performance metrics for impact analysis
 * - Causality tracking (why changes were made)
 * - Context for debugging (session, workspace)
 *
 * Design notes:
 * - Append-only (no updates or deletes except via CASCADE)
 * - Idempotency key prevents duplicate entries on retry
 * - Partitioning by created_at recommended at 50M+ rows
 */
export const capabilityAudit = pgTable("capability_audit", {
    id: uuid("id").primaryKey().defaultRandom(),
    // ===================
    // OWNERSHIP
    // ===================
    userId: text("user_id")
        .notNull()
        .references(() => user.id, { onDelete: "cascade" }),
    // ===================
    // WHAT CHANGED
    // ===================
    /** Type of capability change */
    capabilityType: text("capability_type").$type().notNull(),
    /** Detailed change payload (type depends on capabilityType) */
    change: jsonb("change").$type(),
    /** Human-readable reason for the change */
    reason: text("reason"),
    // ===================
    // PERFORMANCE IMPACT
    // ===================
    /** Performance metrics before the change */
    performanceBefore: jsonb("performance_before").$type(),
    /** Performance metrics after the change */
    performanceAfter: jsonb("performance_after").$type(),
    // ===================
    // CONTEXT
    // ===================
    /** MCP session ID where change originated */
    sessionId: uuid("session_id"),
    /** Workspace ID (hashed) where change originated */
    workspaceId: text("workspace_id"),
    /** Client type that triggered the change */
    clientType: text("client_type"), // "vscode", "mcp", "web", "cli"
    // ===================
    // IDEMPOTENCY
    // ===================
    /** Unique key to prevent duplicate audit entries on retry */
    idempotencyKey: text("idempotency_key").unique(),
    // ===================
    // TIMESTAMPS
    // ===================
    createdAt: timestamp("created_at").defaultNow().notNull(),
});
// =============================================================================
// RELATIONS
// =============================================================================
export const capabilityAuditRelations = relations(capabilityAudit, ({ one }) => ({
    user: one(user, {
        fields: [capabilityAudit.userId],
        references: [user.id],
    }),
}));
